import { CardInstance, GameState, cardDef, getCardScript, isLegalAction, rezCostOf, availableCredits } from '../../core';
import { rezCost, stealthCredits, threatLevel, TurnFlag, turnFlag } from '../../core/engine/cardEffects';
import { canBreakSubroutinesWith, iceScript, iceSubroutines, iceSubtypes, isBioroid } from '../../core/engine/ice';
import { SubEffect, SubFacts, bioroidBreakClicks, breakPlans, bypassesAhead, plannedSubroutines, runBypasses, subroutineFacts } from '../runs';
import { CARDS, clickMoneyOf, turnIncomeOf } from '../cards';
import type { HoldFacts } from '../cards/types';
import { counters } from '../../core/engine/cardEffects';
import { turnKey } from '../../core/engine/helpers';
import { plan, pricing, withPricing } from '../pricing';
import { memo } from '../valueModel';

/**
 * Owner: does a server hold (Step 4 Stage A, spec-step4-corp-core.md 1.4; registry row "what holds a server").
 *
 * One function, serverHold, answers for the horizons the Corp counts today:
 *  - 'runnerTurn': can the Runner get in on its next turn, against the cheapest set of ice the Corp can afford to rez
 *    (holdCost's count, moved here from countedScore.ts);
 *  - 'restOfTurn' (Stage D item 3, F1): the same walk from a different start, the rest of the Runner's turn under way
 *    once its run is over (TurnFrom: the clicks it has left, the credits it is left with, no turn-start money or
 *    counters again, its first draw of the turn taken if it was): what rez money keeps for the rest of this turn;
 *  - 'thisRun': can the Runner get through the rest of the run under way with its credits now (stopCost's count, moved
 *    here from rezModel.ts).
 * The Corp rezzes ice as it is approached (rules 3.4.3a, 6.4.3, 6.9.2b); unrezzed ice is passed (6.9.2c); a bypassed
 * ice's subroutines never resolve (6.5.8a-b). Capability from public facts, not our Runner AI's choice; no Runner grip
 * and no deck order is read (10.2.2a).
 *
 * Both horizons are answered by one walk of the Runner's turn (Stage D item 1, below: "The walk"), from the same facts;
 * they differ in the Runner's budget, where the walk starts, and how many runs it may make. `margin` and `entries` are
 * read by the ordinary moves (candidates.ts, placement.ts) as sort keys and by the ice move's fall.
 */

export interface HoldOptions {
  /**
   * 'runnerTurn' (the Runner's next turn, runnerBudget), 'thisRun' (the run under way, the Runner's credits now) or
   * 'restOfTurn' (the rest of the Runner's turn under way once its run is over, runnerBudget of restOfTurn).
   */
  when: 'runnerTurn' | 'thisRun' | 'restOfTurn';
  /** The credits the Corp may spend on rezzes ('thisRun' defaults to its credits now). */
  corpCredits?: number;
  /** 'restOfTurn': the Runner's credits once the run under way is over (default its credits now). */
  runnerCredits?: number;
  /** 'thisRun': the approached ice's position (default the run's icePosition); the ice from it inward is counted. */
  from?: number;
  /** 'thisRun': ice that must be rezzed (the approached ice, priced at its rez cost; stopCost's `ice`). */
  mustRez?: string[];
  /** 'thisRun': whether the unrezzed ice further in may be rezzed too (stopCost's `further`; default true). */
  further?: boolean;
}

export interface Hold {
  /**
   * Some affordable rez set keeps the Runner out ('runnerTurn': over its whole turn, a run that fails followed by another;
   * 'thisRun': the run under way).
   */
  holds: boolean;
  /** The cheapest holding rez set (instance ids of the ice to rez), or null when none holds. */
  rez: string[] | null;
  /** Its rez spend; Infinity when none holds. */
  rezCost: number;
  /**
   * The Runner's credit need for a single run ('runnerTurn': one run, its clicks split between earning and the run, as
   * before the failed run was counted) against the holding set, or against the affordable set that asks the most (on
   * this one-run need) when none holds. A second run after a failed one can get in where this need is above the budget:
   * then `holds` is false and `margin` above 0 (the brief rev 2, 2.5).
   */
  need: number;
  /** The most the Runner can bring: runnerBudget ('runnerTurn', 'restOfTurn' from its start) or its credits now ('thisRun'). */
  budget: number;
  /** need - budget: above 0 when it holds; above 0 with `holds` false where only a run after a failed one gets in. */
  margin: number;
  /**
   * How many runs on the server one Runner turn gets in on ('runnerTurn': the run sequence of sequenceEntries against
   * the set that asks the most, each run walked with the board the runs before it left, failed runs between them
   * allowed; at least 1 when it does not hold; 'thisRun': 1 or 0). 0 when it holds.
   */
  entries: number;
}

/** Sensitivity knob for the stage 0 report: extra credits granted to the Runner's run (an economy event from the grip it may hold). */
export const CHECK = { runnerExtra: 0 };

/**
 * The Runner's budget for one run on its next turn, from public facts: its credits, and what its installed cards and
 * every click but the run's make (runnerMoney: card entries, never the grip; 5.2.7a). Count inputs F2: before it, 1
 * credit a click, so a loaded Telework Contract was missed (paired +0.0 ± 0.4 at games=3, run 42918973725).
 */
export const runnerBudget = (s: GameState, from: TurnFrom = nextTurn(s)): number => from.credits + runnerEarnings(s, from)[Math.max(0, from.clicks - 1)] + CHECK.runnerExtra;

/**
 * Where a turn's walk starts (Stage D item 3, F1). The Runner's next turn (`rest` false): its turn begins (5.7.1: the
 * turn-start money and counters), every click (maxClicks), its credits now. The rest of the turn under way once its run
 * is over (`rest` true): the clicks it has left, the credits it is left with (`credits`), nothing of the turn's start
 * again; a once-per-turn click ability already used this turn is counted again (toward a richer Runner).
 */
export interface TurnFrom {
  rest: boolean;
  clicks: number;
  credits: number;
}
export const nextTurn = (s: GameState): TurnFrom => ({ rest: false, clicks: Math.max(0, s.runner.maxClicks), credits: s.runner.credits });
export const restOfTurn = (s: GameState, credits = s.runner.credits): TurnFrom => ({ rest: true, clicks: Math.max(0, s.runner.clicks), credits });

const hosted = (c: CardInstance) => counters(c, 'credit');

/**
 * The credits a Runner card's hosted counters pay, no click, during the Runner's turn (HoldFacts.counterCredits,
 * Coalescence: "Hosted power counter: Gain 2 credits. Use this ability only during your turn."; 9.5.1, 1.10.3a). The
 * counters as they stand: a used one is gone, so a turn's start and the rest of a turn read them alike.
 */
export const counterCredits = (c: CardInstance): number => {
  const f = CARDS[c.cardCode]?.holdFacts?.counterCredits;
  return f ? f.credits * counters(c, f.counter) : 0;
};

/**
 * The credits the Runner's installed cards and its clicks but the run's make on its next turn: each installed card's
 * turn-start payment (no more than it holds), then the best set of its paying click abilities (one use each: Telework
 * Contract is once per turn, Fermenter and Rent Rioters are trashed, Pennyshaver pays 1 after its first use), the
 * other clicks 1 credit each (5.2.7a).
 */
export function runnerMoney(s: GameState): number {
  return runnerEarnings(s)[Math.max(0, s.runner.maxClicks - 1)];
}

/**
 * What k earning clicks make on the Runner's next turn, for k = 0 .. maxClicks (runnerMoney is k = maxClicks - 1): each
 * installed card's turn-start payment (no more than it holds), then the best set of its paying click abilities within
 * the k clicks (one use each), the other clicks 1 credit each (5.2.7a). The hold walk splits the turn's clicks between
 * earning and the rest (brief 5.3) and reads this for both. From the rest of a turn (`from.rest`): k = 0 .. its clicks left,
 * with no turn-start payment or turn-start counter (paid or placed already this turn).
 */
export function runnerEarnings(s: GameState, from: TurnFrom = nextTurn(s)): number[] {
  const rig = [...s.runner.rig.programs, ...s.runner.rig.hardware, ...s.runner.rig.resources];
  let drip = 0;
  const uses: { clicks: number; credits: number }[] = [];
  for (const c of rig) {
    const pay = turnIncomeOf(c.cardCode);
    if (pay && !from.rest) drip += pay.hosted ? Math.min(pay.credits, hosted(c)) : pay.credits;
    drip += counterCredits(c);
    const m = clickMoneyOf(c.cardCode);
    if (!m) continue;
    let credits = m.credits;
    if (m.hosted === 'cap') credits = Math.min(credits, hosted(c));
    if (m.hosted === 'add') credits += hosted(c);
    if (m.perVirus) credits += m.perVirus.credits * (counters(c, 'virus') + (from.rest ? 0 : m.perVirus.turnStart));
    if (credits > m.clicks) uses.push({ clicks: m.clicks, credits });
  }
  const max = from.clicks;
  const n = Math.min(uses.length, 10);
  const out: number[] = [];
  for (let clicks = 0; clicks <= max; clicks++) {
    let best = clicks;
    for (let mask = 1; mask < 1 << n; mask++) {
      let k = 0;
      let got = 0;
      for (let i = 0; i < n; i++) if (mask & (1 << i)) {
        k += uses[i].clicks;
        got += uses[i].credits;
      }
      if (k <= clicks) best = Math.max(best, got + clicks - k);
    }
    out.push(drip + best);
  }
  return out;
}

/** Does the server hold, and by how much (see the file comment)? */
export function serverHold(state: GameState, server: string, opts: HoldOptions): Hold {
  if (opts.when === 'thisRun') return walkThisRun(state, server, opts);
  if (opts.when === 'restOfTurn') {
    const board = afterRun(state);
    return counted(() => walkRunnerTurn(board, server, opts.corpCredits ?? state.corp.credits, restOfTurn(board, opts.runnerCredits)));
  }
  return counted(() => walkRunnerTurn(state, server, opts.corpCredits ?? state.corp.credits));
}

/**
 * The board of the rest of the turn: the run under way over (its once-per-run uses and run flags gone, 6.8.5, 6.9.6d:
 * the run's rez cost increase among them, which rezCost adds to every ice), once per board on valueModel's memo (dropped
 * when the board is changed in place), so the memos keyed on it (turnIce, the break plans) serve every ask at one rez
 * window.
 */
export function afterRun(state: GameState): GameState {
  return state.activeRun ? memo(state, 'afterRun', () => ({ ...state, activeRun: null })) : state;
}

/** Counted with countingHold up: the rez budget its prices reach does not ask this count again (deal 2138's hang). */
const counted = <T>(f: () => T): T => (pricing().countingHold ? f() : withPricing({ countingHold: true }, f));

/** A copy-free view with this one ice standing in for its unrezzed self (iceCreditNeed reads the board for strength). */
function withIce(state: GameState, ice: CardInstance): GameState {
  const server = Object.values(state.corp.servers).find(v => v.ice.some(c => c.instanceId === ice.instanceId));
  if (!server) return state;
  return { ...state, corp: { ...state.corp, servers: { ...state.corp.servers, [server.id]: { ...server, ice: server.ice.map(c => (c.instanceId === ice.instanceId ? ice : c)) } } } };
}

const withServerIce = (state: GameState, id: string, ice: CardInstance[]): GameState => ({ ...state, corp: { ...state.corp, servers: { ...state.corp.servers, [id]: { ...state.corp.servers[id], ice } } } });

// =====================================================================================================================
// The walk (Stage D item 1 branch 2, brief rev 2 section 5): the count as a model of the Runner's turn
// =====================================================================================================================
//
// With a rez set S, the Runner's turn is walked from public facts (10.2.2): for 'runnerTurn' from the board at its turn
// start (5.7.1: Botulus and Tranquilizer counters placed, Tranquilizer's and Lycian's derez), its clicks split between
// earning (runnerEarnings), the run and the clicks the run spends; for 'thisRun' from the run under way. The run meets
// the ice outermost first (6.9.2): unrezzed ice outside S is passed (6.9.2c), ice of S is rezzed as it is approached
// (6.4.3) and its rez-time facts apply (Flyswatter's purge), bypassed ice is skipped (6.5.8a, runBypasses as before).
// At each rezzed ice the Runner chooses which subroutines to break and how (a break plan from breakPlans, Botulus's
// counters, the ice's own click or credit ability), and the rest resolve in printed order against the state the walk
// carries (9.8.7b). Clicks, counters, grip cards and once-a-run uses are shared along the run (1.16.1: a cost is paid in
// full). The walk carries facts, never worths (ruling 5): it reads subroutineFacts, the card entries' holdFacts and
// breakPlans' credits and spends, and calls no price.
//
// The failed run (Stage D item 1 follow-up 1, brief rev 2 section 2). On the Runner's turn a run that ends before its
// breach (6.1.4) is not the end of the turn: the turn goes on from the state the run left and the target may be run
// again while clicks remain (the truth of `holds` is the whole turn: Ping's tag cleared before a second run,
// Thunderbolt's gained subroutine gone with its run). The Runner may let a run end on purpose (an ending subroutine left
// unbroken, an ending toll taken). What stays: the ice the Corp rezzed (their rez-time facts not repeated), the Corp's
// credits and lasting choices (Lycian's subtypes), an ice that trashed itself, the Runner's tags, grip, stack, counters,
// trashed cards and hosted credits. What ends with the run (6.8.5, 6.9.6d): the bad publicity fund (10.6.3b, 6.9.6b),
// Mayfly, Pressure Spike's use, the subroutine a rez gave for the run (Thunderbolt; 9.8.3e is where it sits). It is
// asked behind a gate (passes): only of a rez set a single run does not get through, so `need` and `margin` stay the
// single run's. Not counted (each errs as said):
//  - "X or end the run" is taken as the end (ruling 6; 1.14.5: the Corp chooses), so a stronger X (Ballista's program
//    trash, not modelled) is missed: toward "does not hold" (registry debt);
//  - the rez set is fixed and each ice of it is rezzed on the first run that approaches it with the Corp able to pay;
//    the Corp may decline a rez on the first run and make it on the second (6.4.3): toward "does not hold";
//  - Tatu-Bola's swap after it is passed (the Corp 4 richer, an unknown ice met on the next run): toward "does not hold";
//  - over several servers, a failed run on one server made only to drain the Corp for another is not walked (the Corp
//    may decline that rez; the fixed set cannot say so): a retry is on the same target, before the next one.
//
// The pool is not carried: each node works out the least credits in the Runner's pool that get it through from there
// (every effect on the pool is monotone: a payment adds, a condition sets a floor, a loss of n adds n above 0). So one
// pass answers the least the Runner must bring, for every click split, with no search over the credits.

/** No way through. */
const FAIL = Infinity;

/** The pool needed before losing n credits from it, `after` needed after (a loss takes no more than the pool holds). */
const lose = (after: number, n: number): number => (after > 0 ? after + n : 0);

/** A piece of ice as the walk meets it. */
export interface WalkIce {
  /** The ice, rezzed: the subroutines and subtypes it is met with (gathered; the search reads only `id`). */
  card: CardInstance;
  id: string;
  /** Rezzed when the walk starts (the Runner's turn start applied). */
  rezzed: boolean;
  rezCost: number;
  /** In the rez set: the Corp rezzes it as it is approached (6.4.3). */
  inS: boolean;
  /** Skipped by the Runner's bypasses (runBypasses, bypassesAhead; 6.5.8a). */
  bypassed: boolean;
  subs: SubFacts[];
  types: string[];
  /** Rig indexes of the Botulus programs it hosts ("Hosted virus counter: Break 1 subroutine on host ice"). */
  botulus: number[];
  /** Hosted cards that bypass it for credits (Physarum Entangler): rig index, credits a subroutine, the subtype it can't bypass. */
  bypassers: { idx: number; per: number; unless: string }[];
  /** Its own break ability for credits ("3 credits: Break 1 subroutine on this ice", N-Pot). */
  selfCredits?: number;
  /** A bioroid: the Runner may break its subroutines with clicks (bioroidBreakClicks, by the number broken). */
  bioroid: boolean;
  breakClicks: number[];
  /** Botulus may break its subroutines (not Semak-samun's fracters-only). */
  anyBreaker: boolean;
  rezFacts?: HoldFacts['rezDuringRun'];
  /** What the Runner meets as the encounter begins (6.9.3a: Funhouse, Seraph, Jaguarundi; Paywall). */
  encounterFacts?: HoldFacts['encounter'];
  /** Rig indexes of the hosted cards that give it subtypes (Chromatophores): a Corp trash of one changes them. */
  granters: number[];
  /** 'thisRun': the encounter with it is under way; the subroutines already broken. */
  broken?: boolean[];
  /** The subroutine it gains after its others when the Corp rezzes it during a run (Thunderbolt Armaments, 9.8.3e; its +1 strength is not modelled, the todo in tests/holdWalk.test.ts). */
  rezGains?: SubFacts;
  /** Its rez costs the Corp 1 bad publicity or the Runner 1 tag, the Corp's choice (holdFacts.rezBadPublicityOrTag). */
  liability: boolean;
  /** Unrezzed at the walk's start, and the Corp chooses its subtypes when it rezzes it (holdFacts.rezChoosesSubtypes, Lycian): the sets it may choose. `types` is then without a choice. */
  choices?: string[][];
}

/** One run of the walk's turn: its server and its ice, innermost first (as the server lists them). */
export interface WalkTarget {
  server: string;
  ice: WalkIce[];
}

/** The ice as the search reads it: no card, so nothing of the board but what was gathered. */
export type SearchIce = Omit<WalkIce, 'card'>;
export interface SearchTarget {
  server: string;
  ice: SearchIce[];
}
export const searchTarget = (t: WalkTarget): SearchTarget => ({ server: t.server, ice: t.ice.map(searchIce) });
function searchIce(w: WalkIce): SearchIce {
  const out: Partial<WalkIce> = { ...w };
  delete out.card;
  return out as SearchIce;
}

/** What the rig's cards are to the search. */
export interface RigFacts {
  /** A trojan (Bumi 1.0 may trash it). */
  trojan: boolean;
  /** Trashed by a purge (Physarum Entangler). */
  purgeTrash: boolean;
  /** A breaker or Botulus: its counters are read (memo key). */
  counted: boolean;
}

/**
 * Everything the search reads besides its targets and its state, gathered from the board once per question (Stage D
 * item 1, the time stop's ruling 4.3: a pure search, so the gathered question is its own cache key). Break plans and
 * subtypes are gathered for every number of subroutines and every set of the hosted cards that give subtypes gone.
 */
export interface WalkBoard {
  badPublicity: number;
  threat: number;
  hq: number;
  tags: number;
  grip: number;
  rig: RigFacts[];
  lenders: Lender[];
  /** `${ice id}|${subroutines to break}|${granters gone}|${the Corp's choice of subtypes at rez, by index, or ''}`. */
  plans: Record<string, WalkPlan[]>;
  /** `${ice id}|${granters gone}|${choice}` (some gone, or a choice made). */
  types: Record<string, string[]>;
  /** plan.bypass: the Runner's own bypasses (Physarum Entangler) are tried. */
  bypass: boolean;
  /** The cards the turn's first basic draw gives (Verbal Plasticity: "The first time each turn you take the basic action to draw 1 card, instead draw 2 cards"; the engine's firstBasicDraw); 1 without one. */
  firstDraw: number;
  /** What the Runner's cards do as each run begins (6.9.1c): RunBegin, by rig index, in rig order. */
  runBegins: RunBegin[];
}

/**
 * A Runner card that acts as a run begins (follow-up 4): Side Hustle's credits (HoldFacts.runBeginCredits: `hosted` now,
 * `place` a run, all taken at `takeAllAt`, then trashed and `draw`), Knickknack's trash for cost (firstRunTrashForCost,
 * as the bound: `costs`, the printed install cost of each rig card; `used`, its first run of the turn is over).
 */
export interface RunBegin {
  idx: number;
  credits?: { hosted: number; place: number; takeAllAt: number; draw: number };
  trashForCost?: { draw: number; costs: number[]; used: boolean };
}

/** The state the walk carries (brief 5.1), but the Runner's pool: the walk works out the least pool a way needs. */
export interface WalkState {
  clicks: number;
  tags: number;
  grip: number;
  stack: number;
  /** The turn's first basic draw is taken (WalkBoard.firstDraw). */
  drew: boolean;
  /** The Corp's subtype choices for ice rezzed during the walk (`${ice id}:${index into choices}`, sorted; Lycian). */
  chose: string[];
  corp: number;
  /** Credits the Runner can spend only during this run (the bad publicity fund, filled at each run's start, 10.6.3a-b; Overclock's). */
  fund: number;
  /** Bad publicity the Corp took during the walk (a liability rez): in the fund from the next run on (10.6.3c). */
  bp: number;
  /** Credits on cards that pay during runs (runCredits: no stealth card's), any cost but a stealth part: shared through the turn. */
  hosted: number;
  /** Credits on stealth cards (runCredits): a plan's stealth part, and any other cost during a run too. */
  stealth: number;
  /** Counters on each rig card (by rig index). */
  virus: number[];
  power: number[];
  /** Rig indexes trashed during the walk. */
  gone: number[];
  /** Ice rezzed during the walk. */
  up: string[];
  /** Pressure Spike's once-a-run boost used this run. */
  spike: boolean;
  /** Rig indexes trashed when the run ends (Mayfly). */
  mayfly: number[];
  /** Ice that trashed itself during the walk ("Trash this ice"): gone for the rest of the turn. */
  trashed: string[];
  /** This run changed something a later run reads in the Runner's favour (Walk.ended has the list). */
  moved: boolean;
  /** Runs begun during the walk (WalkBoard.runBegins: Side Hustle's credits placed, Knickknack's first run). */
  runs: number;
}

/** A break plan as the walk spends it: breakPlans' credits and its spends, by rig index. */
export interface WalkPlan {
  breaker: number;
  credits: number;
  stealth: number;
  counter?: { idx: number; kind: 'virus' | 'power'; n: number };
  grip: number;
  mayfly: boolean;
  spike: boolean;
}

/** What the walk does not carry (trashing or bouncing a Runner card, the Corp's own side, a jack out it may take). */
const INERT = new Set<SubEffect['kind']>(['trashInstalled', 'toGrip', 'iceStrengthThisRun', 'corpSide', 'mayJackOut', 'unknown']);
/** A subroutine that changes nothing the walk carries: breaking it never helps, so the walk leaves it to resolve. */
const inert = (f: SubFacts) => !f.orEndRun && f.does.every(e => INERT.has(e.kind));

/** A subroutine whose resolution ends the run whatever the state ("End the run.", "X or end the run": ruling 6). */
const alwaysEnds = (f: SubFacts) => !f.when && !f.unless && (f.orEndRun || f.does.some(e => e.kind === 'endRun' && !e.if));

/** The board the walk starts from: the rig, its counters, and the ice derezzed by then (brief 5.2). */
export interface WalkStart {
  rig: CardInstance[];
  index: Map<string, number>;
  virus: number[];
  power: number[];
  derezzed: Set<string>;
  /** 'runnerTurn': the Runner's next turn (a run under way is not part of it). */
  runnerTurn: boolean;
  /** A turn's start (5.7.1) comes first: its counters placed, Lycian derezzed; false for the rest of a turn under way. */
  fresh: boolean;
  /** The ice the turn's end derezzes by the Corp's pick (turnEndDerezPicks; a fresh start only). */
  picked: string[];
}

/** Every way of taking `k` of `list`, in list order. */
const choose = <T>(list: T[], k: number): T[][] =>
  k === 0 ? [[]] : list.flatMap((x, i) => choose(list.slice(i + 1), k - 1).map(rest => [x, ...rest]));

/**
 * The ice the end of the Runner's turn derezzes by its next turn (HoldFacts.turnEndDerez, Lightning Laboratory), as the
 * ways it can go: with `count` or fewer rezzed on the server it was used on, all of them (one way); with more, the Corp
 * picks `count` of them (the engine asks the Corp; its AI's answer is a valuation pick the count cannot read), and each
 * pick is a way (follow-up 4, design answer 7, ruling 8 (a): a server holds only if it holds for every pick). Only the
 * servers in `servers` are asked (no other server's walk reads that ice); [[]] when there is nothing to derez.
 */
export function turnEndDerezPicks(state: GameState, servers?: string[]): string[][] {
  let picks: string[][] = [[]];
  const ids = Object.keys(state.corp.servers);
  for (const a of state.corp.scoreArea) {
    const f = CARDS[a.cardCode]?.holdFacts?.turnEndDerez;
    const at = f ? turnFlag(state, `${f.flag}:${a.instanceId}`) : 0;
    const id = at > 0 ? ids[at - 1] : undefined;
    if (!f || id === undefined || (servers && !servers.includes(id))) continue;
    const up = (state.corp.servers[id]?.ice ?? []).filter(c => c.isRezzed).map(c => c.instanceId);
    const ways = up.length <= f.count ? [up] : choose(up, f.count);
    picks = picks.flatMap(p => ways.map(w => [...p, ...w]));
  }
  return picks;
}

/**
 * The walk's start: the run under way (`runnerTurn` false), the Runner's next turn, or (`fresh` false) the rest of this
 * turn. A next turn's start has the ice of `picked` derezzed (one way of turnEndDerezPicks; by default its first).
 */
export function walkStart(state: GameState, runnerTurn: boolean, fresh = runnerTurn, picked?: string[]): WalkStart {
  const rig = [...state.runner.rig.programs, ...state.runner.rig.hardware, ...state.runner.rig.resources];
  const index = new Map(rig.map((c, i) => [c.instanceId, i]));
  const virus = rig.map(c => counters(c, 'virus'));
  const power = rig.map(c => counters(c, 'power'));
  const derezzed = new Set<string>();
  if (runnerTurn && fresh) {
    // When a turn ends, Lycian Multi-Munition derezzes itself: by the Runner's next turn it is unrezzed
    for (const sv of Object.values(state.corp.servers)) for (const c of sv.ice) if (c.isRezzed && CARDS[c.cardCode]?.holdFacts?.turnEndDerezSelf) derezzed.add(c.instanceId);
    // 5.7.1d: the Runner's turn begins: Botulus and Tranquilizer place a counter, then Tranquilizer derezzes its host at 3
    rig.forEach((c, i) => {
      const t = CARDS[c.cardCode]?.holdFacts?.runnerTurnStart;
      if (!t) return;
      if (t.counters.kind === 'virus') virus[i] += t.counters.n;
      if (t.counters.kind === 'power') power[i] += t.counters.n;
      if (t.derezHostAt !== undefined && c.hostedOnId && virus[i] >= t.derezHostAt) derezzed.add(c.hostedOnId);
    });
  }
  // When the Runner's turn ends, Lightning Laboratory derezzes the ice of the Corp's pick: by its next turn it is unrezzed
  const pick = runnerTurn && fresh ? (picked ?? turnEndDerezPicks(state)[0]) : [];
  for (const id of pick) derezzed.add(id);
  return { rig, index, virus, power, derezzed, runnerTurn, fresh: runnerTurn && fresh, picked: pick };
}

/** The server's ice as the walk meets it, innermost first; inS and bypassed are set per rez set. */
export function walkIce(state: GameState, start: WalkStart, ice: CardInstance[]): WalkIce[] {
  // The subroutines broken on the encounter under way are this run's (review R2): a 'runnerTurn' question is about the
  // Runner's next turn, where every encounter is new (6.9.3)
  const encounter = start.runnerTurn ? undefined : state.activeRun?.encounter;
  // The Corp's identity: what ice of some subtypes gains when it is rezzed during a run (Thunderbolt Armaments)
  const anyIce = CARDS[state.corp.identity?.cardCode]?.holdFacts?.rezDuringRun?.anyIce;
  return ice.map(c => {
    const rezzed = c.isRezzed && !start.derezzed.has(c.instanceId);
    const choices = rezzed ? undefined : CARDS[c.cardCode]?.holdFacts?.rezChoosesSubtypes;
    // An ice whose subtypes the Corp chooses at its rez is met without an earlier choice (the derez clears it)
    const up = choices ? { ...c, isRezzed: true, chosenSubtypes: undefined } : c.isRezzed ? c : { ...c, isRezzed: true };
    const view = withIce(state, up);
    const hostedHere = (f: (x: CardInstance) => boolean) => start.rig.flatMap((r, i) => (r.hostedOnId === c.instanceId && f(r) ? [i] : []));
    const bypassers = hostedHere(r => !!CARDS[r.cardCode]?.holdFacts?.hostBypass).map(i => {
      const b = CARDS[start.rig[i].cardCode].holdFacts!.hostBypass!;
      return { idx: i, per: b.creditsPerSubroutine, unless: b.unlessSubtype };
    });
    const subs = plannedSubroutines(view, up).map(sub => subroutineFacts(sub.label));
    const bioroid = isBioroid(c);
    return {
      card: up,
      id: c.instanceId,
      rezzed,
      rezCost: rezCostOf(state, c),
      inS: false,
      bypassed: false,
      subs,
      types: iceSubtypes(up, state),
      botulus: hostedHere(r => !!CARDS[r.cardCode]?.holdFacts?.breaksHostSubroutine),
      bypassers,
      selfCredits: iceScript(c)?.runnerBreakCost,
      bioroid,
      breakClicks: bioroid ? Array.from({ length: subs.length + 2 }, (_, y) => bioroidBreakClicks(up, y)) : [],
      anyBreaker: canBreakSubroutinesWith(c, null),
      rezFacts: CARDS[c.cardCode]?.holdFacts?.rezDuringRun,
      encounterFacts: CARDS[c.cardCode]?.holdFacts?.encounter,
      granters: hostedHere(r => !!getCardScript(r.cardCode)?.grantsIceSubtypes?.length),
      broken: encounter?.iceId === c.instanceId ? [...encounter.broken] : undefined,
      // AP and destroyer are printed subtypes only (iceSubtypes reads barrier, code gate and sentry, the ones a card grants)
      rezGains: anyIce && (cardDef(c).keywords ?? '').toLowerCase().split(/\s*-\s*/).some(k => anyIce.subtypes.includes(k)) ? subroutineFacts(anyIce.gains) : undefined,
      liability: !!CARDS[c.cardCode]?.holdFacts?.rezBadPublicityOrTag,
      choices,
    };
  });
}

/**
 * A server's ice as met (walkIce), once per board, server and kind of start: serverHold's question and the run sequence's
 * ask it of the same boards (the 14:39Z ruling: gathered once; a turn's start or the rest of a turn (startKind), and the
 * key names the start's kind so a 'thisRun' start is never served the turn's ice). On valueModel's memo, so it is
 * dropped when the board is changed in place.
 */
function turnIce(state: GameState, start: WalkStart, server: string): WalkIce[] {
  const ice = state.corp.servers[server]?.ice ?? [];
  // A turn's-end pick of this server's ice (turnEndDerezPicks) is a different start for it
  const picked = start.picked.length ? ice.filter(c => start.picked.includes(c.instanceId)).map(c => c.instanceId) : [];
  return memo(state, `turnIce:${startKind(start)}:${server}${picked.length ? `:${picked}` : ''}`, () => walkIce(state, start, ice));
}


/** A start's kind in a memo key: 0 the run under way, 1 the next turn, 2 the rest of this turn. */
const startKind = (start: WalkStart): number => (!start.runnerTurn ? 0 : start.fresh ? 1 : 2);

/** The board with the hosted subtype-giving cards at rig indexes `off` taken off (for the ice's subtypes and plans). */
function without(state: GameState, start: WalkStart, off: number[]): GameState {
  if (!off.length) return state;
  const ids = new Set(off.map(i => start.rig[i].instanceId));
  return { ...state, runner: { ...state.runner, rig: { ...state.runner.rig, programs: state.runner.rig.programs.filter(c => !ids.has(c.instanceId)) } } };
}

/** The walk's board for `targets` (WalkBoard): everything the search reads, from the board. */
export function walkBoard(state: GameState, start: WalkStart, targets: WalkTarget[]): WalkBoard {
  // Each ice's break plans, by the number of subroutines, worked out once per board (time condition: not once per rez
  // set), on valueModel's memo (review R3: dropped when the board is changed in place, keyed by the pricing context);
  // by the walk's kind too, as its start reads the rig
  const cache = memo(state, `walkPlans:${startKind(start)}`, () => new Map<string, WalkPlan[]>());
  const plans: Record<string, WalkPlan[]> = {};
  const types: Record<string, string[]> = {};
  const ices = new Map(targets.flatMap(t => t.ice.map(i => [i.id, i] as const)));
  for (const ice of ices.values()) {
    const n = ice.subs.length + (ice.rezGains ? 1 : 0);
    for (let mask = 0; mask < 1 << ice.granters.length; mask++) {
      const off = ice.granters.filter((_, k) => mask & (1 << k));
      const board = without(state, start, off);
      for (const k of ['', ...(ice.choices ?? []).map((_, i) => String(i))]) {
        const card = k === '' ? ice.card : { ...ice.card, chosenSubtypes: ice.choices![Number(k)] };
        if (off.length || k !== '') types[`${ice.id}|${off}|${k}`] = iceSubtypes(card, board);
        for (let z = 1; z <= n; z++) {
          const key = `${ice.id}|${z}|${off}|${k}`;
          let list = cache.get(key);
          if (!list) cache.set(key, (list = planFor(board, start, card, z)));
          plans[key] = list;
        }
      }
    }
  }
  const borrows = [...ices.values()].some(i => i.subs.some(f => f.does.some(e => e.kind === 'borrow')));
  return {
    badPublicity: state.corp.badPublicity,
    threat: threatLevel(state),
    hq: state.corp.hq.length,
    tags: state.runner.tags,
    grip: state.runner.grip.length,
    rig: start.rig.map(c => {
      const keywords = cardDef(c).keywords ?? '';
      return { trojan: /\btrojan\b/i.test(keywords), purgeTrash: !!CARDS[c.cardCode]?.holdFacts?.trashedOnPurge, counted: !!CARDS[c.cardCode]?.holdFacts?.breaksHostSubroutine || /icebreaker/i.test(keywords) };
    }),
    lenders: borrows ? lenders(state, targets) : [],
    plans,
    types,
    bypass: !!plan().bypass,
    firstDraw: [...start.rig, state.runner.identity].reduce((n, c) => Math.max(n, (c && getCardScript(c.cardCode)?.modifiers?.firstBasicDraw) || 1), 1),
    runBegins: runBegins(state, start),
  };
}

/**
 * The rig's cards that act as a run begins (WalkBoard.runBegins), from the board: Side Hustle's credits as they stand;
 * Knickknack's first run of the turn over from the rest of a turn where a run has begun this turn ("The first time each
 * turn a run begins"; still open if it was installed this turn, as the engine's once-per-turn use is its own).
 */
function runBegins(state: GameState, start: WalkStart): RunBegin[] {
  const begun = start.runnerTurn && !start.fresh && state.runsThisTurn.length > 0;
  return start.rig.flatMap((c, idx) => {
    const f = CARDS[c.cardCode]?.holdFacts;
    if (!f?.runBeginCredits && !f?.firstRunTrashForCost) return [];
    const out: RunBegin = { idx };
    if (f.runBeginCredits) out.credits = { hosted: hosted(c), ...f.runBeginCredits };
    if (f.firstRunTrashForCost) {
      const used = begun && c.installedTurn !== turnKey(state);
      out.trashForCost = { draw: f.firstRunTrashForCost.draw, costs: start.rig.map(r => cardDef(r).cost ?? 0), used };
    }
    return [out];
  });
}

/** breakPlans for `z` of the ice's subroutines, as the walk spends them (rig indexes). */
function planFor(board: GameState, start: WalkStart, card: CardInstance, z: number): WalkPlan[] {
  return breakPlans(withIce(board, card), card, z).flatMap(({ plan: p, spends }) => {
    const breaker = start.index.get(p.breaker.instanceId);
    if (breaker === undefined) return [];
    const c = spends.counters;
    const idx = c ? start.index.get(c.cardId) : undefined;
    return [{
      breaker,
      credits: p.credits,
      stealth: spends.stealthCredits ?? 0,
      counter: c && idx !== undefined ? { idx, kind: c.kind, n: c.n } : undefined,
      grip: spends.gripCards ?? 0,
      mayfly: !!spends.trashesBreaker,
      spike: !!spends.oncePerRun,
    }];
  });
}

/** The walk (exported with its parts for tests/holdWalkReference.test.ts, the brute-force reference; brief section 6). */
export class Walk {
  /** Per target and ice position: the rez-set and bypass flags of that ice and every ice inward of it, the part of the
   * set an approach there reads (a memo shared across the rez sets of one question keys on it). */
  private readonly inner: string[][];
  /** Per target: the flags of the targets after it (a later run reads all of its ice). */
  private readonly later: string[];
  /** The rig cards whose counters the walk reads (breakers, Botulus): the others' counters stay out of the memo key. */
  private readonly counted: number[];
  /** By run: whether its approaches read the Runner's clicks (key them by clicks). The last run's breach ends the walk, so
   * its clicks are read only by a bioroid's click breaks and a toll paid in clicks; on any other run, by the runs after. */
  private readonly clicksRead: boolean[];
  /** The ice a borrowed subroutine may come from, with its subroutines' facts (borrow). */
  private readonly lenders: Lender[];
  /** A draw can matter (some damage, a grip condition or a grip-spending plan on the way). */
  private readonly drawUseful: boolean;
  /** Removing a tag can matter (some condition or effect reads the Runner's tags). */
  private readonly tagUseful: boolean;

  constructor(
    /** What it reads of the board, gathered (walkBoard): the search has no `state` in scope. */
    private readonly board: WalkBoard,
    private readonly targets: SearchTarget[],
    /** The memo, shared by the walks of one question over its rez sets (keys carry the flags they read). */
    private readonly memo = new Map<string, number>(),
    /**
     * A run that ends is followed by the rest of the turn (the failed run, above): the turn goes on from the state the run
     * left, and the same target is run again while clicks remain. Off for the gate's single runs and for 'thisRun' (a new
     * run is not this run). The two kinds never share a memo (WalkMemos).
     */
    private readonly retries = false,
  ) {
    // Keys name the server and the runs still to make, not the run's index: the last run of a sequence and a single run
    // on the same server share their nodes (sequenceEntries, turnReach)
    const flags = (i: SearchIce) => `${i.inS ? 1 : 0}${i.bypassed ? 1 : 0}`;
    // An approach reads the flags of the ice inward of it; with retries, a run that ends there is run again from the
    // outermost ice, so it reads them all
    this.inner = targets.map(t => t.ice.map((_, pos) => `${t.server}:${t.ice.slice(0, retries ? t.ice.length : pos + 1).map(flags).join('')}`));
    this.later = targets.map((_, j) => targets.slice(j + 1).map(t => `${t.server}:${t.ice.map(flags).join('')}`).join('/'));
    // With retries every run's clicks are read (a run that ends leaves the rest of them for the next)
    this.clicksRead = targets.map((t, j) => retries || j < targets.length - 1 || t.ice.some(i => i.bioroid || i.encounterFacts?.unless?.clicks !== undefined));
    this.counted = board.rig.flatMap((r, i) => (r.counted ? [i] : []));
    const facts = targets.flatMap(t => t.ice.flatMap(i => (i.rezGains ? [...i.subs, i.rezGains] : i.subs)));
    const effects = facts.flatMap(f => f.does);
    const borrows = effects.filter(e => e.kind === 'borrow').length;
    // What a borrow can resolve: the subroutines of every ice it may lend from (borrow, below), gathered
    this.lenders = borrows ? board.lenders : [];
    const lent = this.lenders.flatMap(l => l.facts);
    const all = [...facts, ...lent];
    const allEffects = all.flatMap(f => f.does);
    const encounters = targets.flatMap(t => t.ice.flatMap(i => (i.encounterFacts ? [i.encounterFacts] : [])));
    // A draw helps only when the grip can run short (10.4.4): the most the targets can take from it on one pass (damage,
    // net damage paid instead, X counted at the most tags the walk can carry; each borrow at the most one lent subroutine
    // takes) is more than it holds, or any at all when a run may be made again; a grip condition or a plan that spends
    // grip cards (Audrey v2: a plan with `grip`) always counts
    const most = (list: number[]) => list.reduce((a, b) => Math.max(a, b), 0);
    const sum = (list: number[]) => list.reduce((a, b) => a + b, 0);
    const tagsOf = (f: SubFacts) => sum(f.does.map(e => (e.kind === 'tags' && typeof e.n === 'number' ? e.n : 0)));
    const tagGains = targets.flatMap(t => t.ice.map(i => (i.rezFacts?.tags ?? 0) + (i.encounterFacts?.toll?.tags ?? 0) + (i.encounterFacts?.unless?.tags ?? 0)));
    const tagsMost = board.tags + sum(tagGains) + sum(facts.map(tagsOf)) + borrows * most(lent.map(tagsOf));
    const gripOf = (f: SubFacts) => sum(f.does.map(e => (e.kind === 'damage' ? (e.n === 'runnerTags' ? tagsMost : e.n) : 0))) + (f.unless?.netDamage ?? 0);
    const gripMost = sum(facts.map(gripOf)) + sum(encounters.map(e => e.unless?.netDamage ?? 0)) + borrows * most(lent.map(gripOf));
    const doubling = allEffects.some(e => e.kind === 'tags' && e.n === 'runnerTags');
    // With retries a run may be made again, so any damage can add up past the grip
    this.drawUseful = doubling || allEffects.some(e => e.kind === 'endRun' && e.if?.kind === 'hqMoreThanGrip') || Object.values(board.plans).some(list => list.some(p => p.grip > 0)) || gripMost > board.grip || (retries && gripMost > 0);
    this.tagUseful = all.some(f => f.when?.kind === 'runnerTagsAtLeast') || allEffects.some(e => (e.kind === 'endRun' && e.if?.kind === 'runnerTagsAtLeast') || ((e.kind === 'damage' || e.kind === 'tags') && e.n === 'runnerTags') || (e.kind === 'corpGainsCredits' && e.n === 'perRunnerTag'));
  }

  /** The walk state in a memo key (run j: the clicks only where they are read, the stack where a run may follow). */
  private wsKey(ws: WalkState, j: number): string {
    return `${this.clicksRead[j] ? ws.clicks : '-'}|${ws.tags}|${ws.grip}|${this.retries || j < this.targets.length - 1 ? ws.stack : '-'}|${ws.corp}|${ws.fund}|${ws.hosted}|${ws.stealth}|${this.counters(ws)}|${ws.gone}|${ws.up}|${ws.spike ? 1 : 0}|${ws.mayfly}|${ws.drew ? 1 : 0}|${ws.chose}|${ws.trashed}|${ws.bp}${this.runKey(ws)}${this.retries ? (ws.moved ? '|1' : '|0') : ''}`;
  }

  /** The runs begun, for a memo key, where a card acts as a run begins (once no Side Hustle is left, only whether a run has begun). */
  private runKey(ws: WalkState): string {
    const list = this.board.runBegins;
    if (!list.length) return '';
    return `|${list.some(b => b.credits && !ws.gone.includes(b.idx)) ? ws.runs : Math.min(ws.runs, 1)}`;
  }

  /** The counters the walk reads, for a memo key. */
  private counters(ws: WalkState): string {
    let s = '';
    for (const i of this.counted) s += `${ws.virus[i]},${ws.power[i]};`;
    return s;
  }

  /** The least pool that gets the Runner through every target in order, its turn's clicks in `ws` (runnerTurn). */
  turn(ws: WalkState): number {
    return this.beforeRun(ws, 0);
  }

  /** The least pool from the approach of the ice at `pos` of the first target (thisRun: the run under way). */
  fromIce(ws: WalkState, pos: number): number {
    return this.approach(ws, 0, pos);
  }

  /**
   * Before run j: the Runner may draw (5.2.7c) or remove a tag (5.2.7g: a click and 2 credits) with a click it keeps
   * clear of the runs still to make, then runs (5.2.7f). Earning comes first (runnerEarnings at the turn's start): a
   * credit in the pool earlier is never worse.
   */
  private beforeRun(ws: WalkState, j: number): number {
    const runs = this.targets.length - j;
    if (ws.clicks < runs) return FAIL;
    const key = `b|${this.inner[j][this.targets[j].ice.length - 1] ?? this.targets[j].server}|${this.later[j]}|${ws.clicks}|${ws.tags}|${ws.grip}|${ws.stack}|${ws.corp}|${ws.hosted}|${ws.stealth}|${this.counters(ws)}|${ws.gone}|${ws.up}|${ws.drew ? 1 : 0}|${ws.chose}|${ws.trashed}|${ws.bp}${this.runKey(ws)}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    // 6.9.1b, 10.6.3a: the bad publicity fund is filled as each run begins, with what the Corp took on earlier runs
    const fund = this.board.badPublicity + ws.bp;
    let best = this.runBegins({ ...ws, clicks: ws.clicks - 1, spike: false, fund, moved: false }, w => this.approach(w, j, this.targets[j].ice.length - 1));
    if (ws.clicks > runs) {
      if (this.drawUseful && ws.stack > 0) {
        // 5.2.7c; the turn's first draw may give more (WalkBoard.firstDraw), at most the stack
        const n = Math.min(ws.stack, ws.drew ? 1 : this.board.firstDraw);
        best = Math.min(best, this.beforeRun({ ...ws, clicks: ws.clicks - 1, grip: ws.grip + n, stack: ws.stack - n, drew: true }, j));
      }
      if (this.tagUseful && ws.tags > 0) best = Math.min(best, this.beforeRun({ ...ws, clicks: ws.clicks - 1, tags: ws.tags - 1 }, j) + 2);
    }
    this.memo.set(key, best);
    return best;
  }

  /**
   * The run begins (6.9.1c; WalkBoard.runBegins): each Side Hustle places its credit and, at its payout, the Runner takes
   * all of them (1.10.4a), trashes it and draws; the first time this turn, Knickknack's trash as the bound (the largest
   * printed install cost among the other installed cards, the card kept) and a draw. The pool needed before a gain is the
   * rest's need less the gain, at least 0 (a gain pays only what comes after it). A credit placed is progress a later
   * run reads in the Runner's favour (`moved`).
   */
  private runBegins(ws: WalkState, then: (w: WalkState) => number): number {
    const list = this.board.runBegins;
    if (!list.length) return then(ws);
    const draw = (x: WalkState, n: number): WalkState => {
      const k = Math.min(n, x.stack);
      return { ...x, grip: x.grip + k, stack: x.stack - k };
    };
    let w: WalkState = { ...ws, runs: ws.runs + 1 };
    let gain = 0;
    for (const b of list) {
      if (w.gone.includes(b.idx)) continue;
      if (b.credits) {
        const held = b.credits.hosted + b.credits.place * w.runs;
        w = { ...w, moved: true };
        if (held >= b.credits.takeAllAt) {
          gain += held;
          w = draw({ ...w, gone: [...w.gone, b.idx].sort((x, y) => x - y) }, b.credits.draw);
        }
      }
      if (b.trashForCost && ws.runs === 0 && !b.trashForCost.used) {
        gain += b.trashForCost.costs.reduce((n, c, i) => (i === b.idx || w.gone.includes(i) ? n : Math.max(n, c)), 0);
        w = draw(w, b.trashForCost.draw);
      }
    }
    return Math.max(0, then(w) - gain);
  }

  /** The breach of run j (6.9.5): the turn goes on to the next target, Mayfly trashed as the run ends. */
  private breach(ws: WalkState, j: number): number {
    if (j + 1 >= this.targets.length) return 0;
    // 6.9.6b, 10.6.3b: what is left in the bad publicity fund goes back to the bank
    return this.beforeRun({ ...ws, fund: 0, gone: [...ws.gone, ...ws.mayfly].sort((a, b) => a - b), mayfly: [] }, j + 1);
  }

  /**
   * Run j ended before its breach (a subroutine or a toll ended it, 6.1.4): with retries the turn goes on from the state
   * it left, which the walk carries (the ice it rezzed stay rezzed, the Corp's credits, the counters, tags and grip, the
   * click spent), and run j is made again while clicks remain; what lasts "for this run" ends with it (the fund goes back,
   * 10.6.3b; Mayfly is trashed; Pressure Spike's use and a rez's gained subroutine, Thunderbolt's, are the run's only).
   * Without retries an ended run fails. A flatline (10.4.4) is not an ended run: the game is over.
   * The cut (109ae85, kept by the design answer of 16:29Z): a run is made again only if it `moved`, that is changed
   * something a later run reads in the Runner's favour. Everything of the brief's 2.2 a failed run leaves for the Runner
   * sets it, and a fact added to "what stays" must be added here: a rez (with it the Corp's credits spent, a lasting
   * choice such as Lycian's, a rez-time fact used up such as Ping's tag; set at any rez, one the Corp pays 0 for too),
   * a Corp gain of credits, an ice that trashed itself. All else a run changes (a click, tags, damage, credits, counters
   * or cards spent) leaves the Runner no better off than at its start, where every way on was open already, so a retry
   * finds nothing new. The brute-force reference (tests/holdWalkReference.test.ts) keeps no cut.
   */
  private ended(ws: WalkState, j: number): number {
    if (!this.retries || !ws.moved) return FAIL;
    return this.beforeRun({ ...ws, fund: 0, gone: [...ws.gone, ...ws.mayfly].sort((a, b) => a - b), mayfly: [] }, j);
  }

  private approach(ws: WalkState, j: number, pos: number): number {
    if (pos < 0) return this.breach(ws, j);
    const at = `${pos}|${this.inner[j][pos]}|${this.later[j]}`;
    const key = `${at}|${this.wsKey(ws, j)}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    const ice = this.targets[j].ice[pos];
    const next = (w: WalkState) => this.approach(w, j, pos - 1);
    let v: number;
    // An ice that trashed itself on an earlier run of the turn is not there (passed as if it were not installed)
    if (ws.trashed.includes(ice.id)) v = next(ws);
    else if (!ice.rezzed && !ws.up.includes(ice.id)) {
      // 6.9.2c: unrezzed ice the Corp does not rez is passed; 6.4.3: ice of S is rezzed as it is approached
      const paid = ws.corp - ice.rezCost;
      v = ice.inS && paid >= 0 ? this.liability({ ...ws, corp: paid, up: [...ws.up, ice.id].sort(), moved: true }, ice, w => this.rezzed(w, ice, next, { key: at, j })) : next(ws);
    } else v = ice.bypassed ? next(ws) : this.encounter(ws, ice, next, { key: at, j });
    this.memo.set(key, v);
    return v;
  }

  /**
   * A liability rez's additional cost (Valentão, Piranhas: "take 1 bad publicity or remove 1 tag"; 1.14.3a), the
   * Corp's choice worse for the Runner (ruling 6): the bad publicity fills the fund from the next run on (10.6.3c), the
   * tag is gone at once. Paid before the rez's own effects.
   */
  private liability(ws: WalkState, ice: SearchIce, then: (w: WalkState) => number): number {
    if (!ice.liability) return then(ws);
    const bp = then({ ...ws, bp: ws.bp + 1 });
    return ws.tags > 0 ? Math.max(bp, then({ ...ws, tags: ws.tags - 1 })) : bp;
  }

  /** The ice was rezzed during this run against its server: its rez-time facts (Flyswatter: purge virus counters). */
  private rezzed(ws: WalkState, ice: SearchIce, next: (w: WalkState) => number, at: Step): number {
    if (ice.choices && this.choiceOf(ice, ws) === '') {
      // Lycian: the Corp chooses the ice's subtypes as it rezzes it, the choice worst for the Runner (ruling 6)
      let worst = -Infinity;
      ice.choices.forEach((_, k) => (worst = Math.max(worst, this.rezzed({ ...ws, chose: [...ws.chose, `${ice.id}:${k}`].sort() }, ice, next, at))));
      return worst;
    }
    let w = ws;
    if (ice.rezFacts?.purgeVirus) {
      // Purging removes every virus counter (10.3.5); Physarum Entangler is trashed by it (its text)
      const purged = this.board.rig.flatMap((r, i) => (r.purgeTrash ? [i] : []));
      w = { ...w, virus: w.virus.map(() => 0), gone: [...new Set([...w.gone, ...purged])].sort((a, b) => a - b) };
    }
    if (ice.rezFacts?.tags) w = { ...w, tags: w.tags + ice.rezFacts.tags };
    // Thunderbolt Armaments: the ice gains its subroutine after its others for the rest of the run (9.8.3e)
    const met = ice.rezGains ? { ...ice, subs: [...ice.subs, ice.rezGains] } : ice;
    const go = (x: WalkState) => (ice.bypassed ? next(x) : this.encounter(x, met, next, at));
    if (ice.rezFacts?.corpMayTrashInstalled === 'trojan') {
      // Bumi 1.0: the Corp may trash 1 installed trojan, the choice worst for the Runner (ruling 6)
      let worst = go(w);
      this.board.rig.forEach((r, i) => {
        if (!w.gone.includes(i) && r.trojan) worst = Math.max(worst, go({ ...w, gone: [...w.gone, i].sort((a, b) => a - b) }));
      });
      return worst;
    }
    return go(w);
  }

  /**
   * An encounter: the Runner's own bypass first (Physarum, its trigger as the active player's), then what the ice does as
   * the encounter begins (6.9.3a), then its choice of the subroutines to break and how; the rest resolve in order.
   */
  private encounter(ws: WalkState, ice: SearchIce, next: (w: WalkState) => number, at: Step): number {
    const subs = ice.subs;
    const types = this.typesOf(ice, ws);
    let best = FAIL;
    if (this.board.bypass) {
      for (const b of ice.bypassers) if (!ws.gone.includes(b.idx) && !types.includes(b.unless)) best = Math.min(best, this.pay(ws, b.per * subs.length, next));
    }
    return Math.min(best, this.tolls(ws, ice, w => this.breaks(w, ice, types, next, at), at));
  }

  /** The ice's subtypes now: a Corp trash of a hosted card that gives subtypes (Chromatophores) takes them away. */
  private typesOf(ice: SearchIce, ws: WalkState): string[] {
    const off = ice.granters.filter(i => ws.gone.includes(i));
    const k = this.choiceOf(ice, ws);
    return off.length || k !== '' ? this.board.types[`${ice.id}|${off}|${k}`] : ice.types;
  }

  /** The Corp's choice of the ice's subtypes at its rez during the walk (its index in `choices`), or '' (none made). */
  private choiceOf(ice: SearchIce, ws: WalkState): string {
    if (!ice.choices) return '';
    const c = ws.chose.find(x => x.startsWith(`${ice.id}:`));
    return c ? c.slice(ice.id.length + 1) : '';
  }

  /**
   * What the ice does as the encounter begins (6.9.3a): a toll unless the Runner pays one of the alternatives, its
   * choice (Funhouse: end the run unless it takes 1 tag; Seraph: lose 3 unless it suffers 2 net damage or takes 1 tag;
   * Jaguarundi at threat 4: a tag unless it spends a click).
   */
  private tolls(ws: WalkState, ice: SearchIce, then: (w: WalkState) => number, at: Step): number {
    const e = ice.encounterFacts;
    if (!e || ice.broken || (e.threatAtLeast !== undefined && this.board.threat < e.threatAtLeast)) return then(ws);
    // Paywall: the Runner loses credits as the encounter begins (6.9.3a), from its pool (10.6.2: not the fund)
    if (e.loses) return lose(this.toll(ws, e, then, at), e.loses);
    return this.toll(ws, e, then, at);
  }

  /** The encounter toll and the alternatives the Runner may pay instead, its choice. */
  private toll(ws: WalkState, e: NonNullable<SearchIce['encounterFacts']>, then: (w: WalkState) => number, at: Step): number {
    if (!e.toll) return then(ws);
    const t = e.toll;
    let best = t.endRun ? this.ended(ws, at.j) : t.loses ? lose(then(ws), t.loses) : then({ ...ws, tags: ws.tags + (t.tags ?? 0) });
    const u = e.unless ?? {};
    if (u.tags) best = Math.min(best, then({ ...ws, tags: ws.tags + u.tags }));
    if (u.netDamage !== undefined && u.netDamage <= ws.grip) best = Math.min(best, then({ ...ws, grip: ws.grip - u.netDamage }));
    if (u.clicks !== undefined && u.clicks <= ws.clicks) best = Math.min(best, then({ ...ws, clicks: ws.clicks - u.clicks }));
    return best;
  }

  /** The Runner's choice of the subroutines to break and how (a plan, Botulus's counters, the ice's own ability). */
  private breaks(ws: WalkState, ice: SearchIce, types: string[], next: (w: WalkState) => number, at: Step): number {
    const subs = ice.subs;
    let best = FAIL;
    // An inert subroutine resolves to nothing (breaking it never helps): left out of the choice and of the resolution
    const open = subs.map((_, i) => i).filter(i => !ice.broken?.[i] && !inert(subs[i]));
    for (let set = 0; set < 1 << open.length; set++) {
      const unbroken = open.filter((_, k) => !(set & (1 << k)));
      // A subroutine left unbroken that always ends the run ends it there: without retries the way fails; with them it is
      // a way to end the run, and breaking a subroutine after it buys nothing (it never resolves)
      const first = unbroken.find(i => alwaysEnds(subs[i]));
      if (first !== undefined && (!this.retries || open.some((i, k) => i > first && set & (1 << k)))) continue;
      const b = open.length - unbroken.length;
      const resolve = (w: WalkState) => this.resolve(w, ice, types, unbroken, 0, next, at);
      if (b === 0) {
        best = Math.min(best, resolve(ws));
        continue;
      }
      const hosted = ice.anyBreaker ? ice.botulus.filter(i => !ws.gone.includes(i)) : [];
      const counters = hosted.reduce((n, i) => n + ws.virus[i], 0);
      for (let x = 0; x <= Math.min(b, counters); x++) {
        const w1 = x ? this.spendBotulus(ws, hosted, x) : ws;
        for (let y = 0; y <= b - x; y++) {
          if (y > 0 && !ice.bioroid && ice.selfCredits === undefined) break;
          const clicks = ice.bioroid && y > 0 ? ice.breakClicks[y] : 0;
          if (clicks > w1.clicks) break;
          const w2 = clicks ? { ...w1, clicks: w1.clicks - clicks } : w1;
          const self = (w: WalkState, then: (w: WalkState) => number) => (ice.selfCredits !== undefined && y > 0 ? this.pay(w, y * ice.selfCredits, then) : then(w));
          const z = b - x - y;
          if (z === 0) {
            best = Math.min(best, self(w2, resolve));
            continue;
          }
          for (const p of this.planList(ice, z, w2)) if (this.usable(w2, p)) best = Math.min(best, self(w2, w => this.payPlan(w, p, resolve)));
        }
      }
    }
    return best;
  }

  private spendBotulus(ws: WalkState, hosted: number[], x: number): WalkState {
    const virus = [...ws.virus];
    let left = x;
    for (const i of hosted) {
      const n = Math.min(left, virus[i]);
      virus[i] -= n;
      left -= n;
    }
    return { ...ws, virus };
  }

  private planList(ice: SearchIce, z: number, ws: WalkState): WalkPlan[] {
    return this.board.plans[`${ice.id}|${z}|${ice.granters.filter(i => ws.gone.includes(i))}|${this.choiceOf(ice, ws)}`] ?? [];
  }

  private usable(ws: WalkState, p: WalkPlan): boolean {
    if (ws.gone.includes(p.breaker) || (p.spike && ws.spike) || p.stealth > ws.stealth || p.grip > ws.grip) return false;
    return !p.counter || (p.counter.kind === 'virus' ? ws.virus : ws.power)[p.counter.idx] >= p.counter.n;
  }

  private payPlan(ws: WalkState, p: WalkPlan, then: (w: WalkState) => number): number {
    const w: WalkState = { ...ws, stealth: ws.stealth - p.stealth, spike: ws.spike || p.spike, grip: ws.grip - p.grip };
    if (p.counter) {
      const list = [...(p.counter.kind === 'virus' ? w.virus : w.power)];
      list[p.counter.idx] -= p.counter.n;
      if (p.counter.kind === 'virus') w.virus = list;
      else w.power = list;
    }
    if (p.mayfly && !w.mayfly.includes(p.breaker)) w.mayfly = [...w.mayfly, p.breaker].sort((a, b) => a - b);
    return this.pay(w, p.credits - p.stealth, then);
  }

  /**
   * Pays `n` credits during the run in the engine's order (spendCredits), which gives the Runner no choice of source: the
   * fund (bad publicity, then the run's bonus credits; 10.6.2: not part of the pool), then the credits on cards that pay
   * during runs (`hosted`, then the stealth cards': Methuselah, Touchstone), then the pool. The pool part is added to what
   * the rest needs. Rule 1.10.3c lets the Runner divide a payment among the allowed sources; the engine does not yet
   * (found-list row 49), and the walk follows the engine: when it gives the choice, a kept stealth credit can beat a pool
   * credit (a later stealth part, a later loss) and pay must try the splits (registry, the hold row's debt).
   */
  private pay(ws: WalkState, n: number, then: (w: WalkState) => number): number {
    const fund = Math.min(n, ws.fund);
    const hosted = Math.min(n - fund, ws.hosted);
    const stealth = Math.min(n - fund - hosted, ws.stealth);
    const w = fund || hosted || stealth ? { ...ws, fund: ws.fund - fund, hosted: ws.hosted - hosted, stealth: ws.stealth - stealth } : ws;
    return then(w) + n - fund - hosted - stealth;
  }

  /** The unbroken subroutines `list` (indexes into ice.subs) resolve one at a time in printed order (9.8.7b). */
  private resolve(ws: WalkState, ice: SearchIce, types: string[], list: number[], k: number, next: (w: WalkState) => number, at: Step): number {
    if (k >= list.length) return next(ws);
    const go = () => this.subroutine(ws, ice.id, types, ice.subs[list[k]], w => this.resolve(w, ice, types, list, k + 1, next, at), at);
    // A borrowing ice (Mycoweb) branches on every subroutine it may lend, each with the rest of its own to resolve: the
    // steps after the first are keyed (`at`: the approach and run; the subroutines as met, those left, the state)
    if (k === 0 || !ice.subs.some(f => f.does.some(e => e.kind === 'borrow'))) return go();
    const key = `s|${at.key}|${ice.subs.length}|${list}|${k}|${this.wsKey(ws, at.j)}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    const v = go();
    this.memo.set(key, v);
    return v;
  }

  /** One subroutine resolves (or the Runner pays its nested cost instead, 1.16.11b). */
  private subroutine(ws: WalkState, card: string, types: string[], f: SubFacts, then: (w: WalkState) => number, at: Step): number {
    if (f.when && !(f.when.kind === 'iceIs' ? types.includes(f.when.subtype) : f.when.kind === 'runnerTagsAtLeast' && ws.tags >= f.when.n)) return then(ws);
    // "X or end the run": the Corp chooses, and the walk takes the end (ruling 6)
    if (f.orEndRun) return this.ended(ws, at.j);
    let best = this.effects(ws, card, f.does, 0, then, at);
    // "unless the Runner pays N" (1.16.11b): paid as it resolves, run-only credits first (10.6.3a: the fund pays any cost
    // during the run)
    if (f.unless?.credits !== undefined) best = Math.min(best, this.pay(ws, f.unless.credits, then));
    // "unless the Runner trashes 1 of their installed cards" (Thunderbolt Armaments): the card it can best spare
    if (f.unless?.trashInstalled) {
      this.board.rig.forEach((_, i) => {
        if (!ws.gone.includes(i)) best = Math.min(best, then({ ...ws, gone: [...ws.gone, i].sort((a, b) => a - b) }));
      });
    }
    if (f.unless?.netDamage !== undefined && f.unless.netDamage <= ws.grip) best = Math.min(best, then({ ...ws, grip: ws.grip - f.unless.netDamage }));
    return best;
  }

  private effects(ws: WalkState, card: string, does: SubEffect[], i: number, then: (w: WalkState) => number, at: Step): number {
    if (i >= does.length) return then(ws);
    const e = does[i];
    const next = (w: WalkState) => this.effects(w, card, does, i + 1, then, at);
    const end = () => this.ended(ws, at.j);
    switch (e.kind) {
      case 'endRun': {
        const c = e.if;
        if (!c) return end();
        // A condition on the pool: the run goes on with a pool over the bound, or ends with one at most it (the ended
        // way only where the rest of the turn needs no more than that)
        if (c.kind === 'runnerCreditsAtMost') {
          const ended = end();
          return Math.min(Math.max(next(ws), c.n + 1), ended <= c.n ? ended : FAIL);
        }
        if (c.kind === 'corpCreditsMoreThanRunner') {
          const ended = end();
          return Math.min(Math.max(next(ws), ws.corp), ended < ws.corp ? ended : FAIL);
        }
        if (c.kind === 'runnerTagsAtLeast') return ws.tags >= c.n ? end() : next(ws);
        if (c.kind === 'threatAtLeast') return this.board.threat >= c.n ? end() : next(ws);
        if (c.kind === 'hqMoreThanGrip') return this.board.hq > ws.grip ? end() : next(ws);
        // Diviner's odd cost: a fact of the grip the walk can't read; left out (the safe side, "does not hold")
        return next(ws);
      }
      case 'runnerLosesClicks':
        return next({ ...ws, clicks: Math.max(0, ws.clicks - e.n) });
      case 'runnerLosesCredits':
        return lose(next(ws), e.n);
      case 'corpGainsCredits':
        return next({ ...ws, corp: ws.corp + (e.n === 'perRunnerTag' ? ws.tags : e.n), moved: true });
      case 'damage': {
        // 10.4.4: more damage than the cards in the grip is a flatline; each point takes a card (10.4.2)
        const n = e.n === 'runnerTags' ? ws.tags : e.n;
        return n > ws.grip ? FAIL : next({ ...ws, grip: ws.grip - n });
      }
      case 'tags':
        return next({ ...ws, tags: ws.tags + (e.n === 'runnerTags' ? ws.tags : e.n) });
      case 'cannotStealOrTrash':
        // Nothing is stolen on this run: as far as the target goes, the run has ended
        return end();
      case 'trashThisIce':
        // "Trash this ice": gone for the rest of the turn (the run goes on inward; a later run does not meet it)
        return next({ ...ws, trashed: [...ws.trashed, card].sort(), moved: true });
      case 'corpMayTrashHqToEndRun':
        return this.board.hq > 0 ? end() : next(ws);
      case 'borrow':
        return this.borrow(ws, card, e.subtype, next, at);
      default:
        // What the walk doesn't carry: trashing or bouncing a Runner card (registry debt: errs toward "does not hold"),
        // the Corp's own side, a jack out the Runner may take
        return next(ws);
    }
  }

  /** Mycoweb: the Corp resolves 1 subroutine of another rezzed ice of the subtype, the one worst for the Runner (ruling 6). */
  private borrow(ws: WalkState, card: string, subtype: string, next: (w: WalkState) => number, at: Step): number {
    let worst = -1;
    for (const l of this.lenders) {
      if (l.id === card || ws.trashed.includes(l.id) || !(l.rezzed || ws.up.includes(l.id)) || !l.types.includes(subtype)) continue;
      for (const f of l.facts) worst = Math.max(worst, this.subroutine(ws, l.id, l.types, f, next, at));
    }
    return worst < 0 ? next(ws) : worst;
  }
}

/** Where an encounter is: its approach's memo key and its run. */
interface Step {
  key: string;
  j: number;
}

/** A borrow's lender: rezzed now, or walked (rezzed when the walk rezzes it), its subroutines but the borrowing ones. */
interface Lender {
  id: string;
  rezzed: boolean;
  types: string[];
  facts: SubFacts[];
}

/** Every ice a borrow may lend from, in board order: the walked ice as met, the rest as the board has it. */
function lenders(state: GameState, targets: WalkTarget[]): Lender[] {
  const walked = new Map(targets.flatMap(t => t.ice.map(x => [x.id, x] as const)));
  return lenderViews(state, walked).flatMap(v => (walked.has(v.id) ? [v.walked!] : v.unwalked ? [v.unwalked] : []));
}

/** Each ice of the board as a lender both ways, in board order: as met when `walked` holds it, and as the board has it (rezzed ice only). */
function lenderViews(state: GameState, walked: Map<string, WalkIce>): { id: string; walked?: Lender; unwalked?: Lender }[] {
  const facts = (c: CardInstance) => iceSubroutines(state, c).filter(sub => !/resolve 1 subroutine on/i.test(sub.label)).map(sub => subroutineFacts(sub.label));
  const out: { id: string; walked?: Lender; unwalked?: Lender }[] = [];
  for (const sv of Object.values(state.corp.servers)) {
    for (const c of sv.ice) {
      const w = walked.get(c.instanceId);
      out.push({
        id: c.instanceId,
        walked: w ? { id: c.instanceId, rezzed: w.rezzed, types: w.types, facts: facts(w.card) } : undefined,
        unwalked: c.isRezzed ? { id: c.instanceId, rezzed: true, types: iceSubtypes(c, state), facts: facts(c) } : undefined,
      });
    }
  }
  return out;
}

/**
 * The run-time credits on the Runner's cards, split with no overlap (audit AI-HOLD-STEALTH-TWICE, found-list row 31):
 * `stealth`, the credits on stealth cards, which pay a plan's stealth part (Corsair) and, during a run, any other cost
 * too; `hosted`, the credits on the other cards that pay during runs, any cost but a stealth part. On the Runner's turn,
 * the rig's (runStealthCredits' stealth cards; Methuselah, Touchstone); during the run under way, the engine's: its run payers
 * (availableCredits less the pool it counts, none with the pool locked, and the fund; Trick Shot's and Aircheck's
 * hosted credits too) and its stealth credits. Read by the turn's first state and the run under way alike.
 */
function runCredits(state: GameState, start: WalkStart): { hosted: number; stealth: number } {
  const run = state.activeRun;
  if (run && !start.runnerTurn) {
    const stealth = stealthCredits(state);
    const pool = run.poolLocked ? 0 : state.runner.credits;
    return { hosted: availableCredits(state, 'runner') - pool - run.bonusCredits - (run.badPublicityCredits ?? 0) - stealth, stealth };
  }
  const sum = (f: (c: CardInstance, stealth: boolean) => boolean) => start.rig.filter(c => f(c, /stealth/i.test(cardDef(c).keywords ?? ''))).reduce((n, c) => n + counters(c, 'credit'), 0);
  return { hosted: sum((c, stealth) => !stealth && !!getCardScript(c.cardCode)?.paysDuringRuns), stealth: sum((_, stealth) => stealth) };
}

/**
 * The walk's first state on the Runner's turn: `clicks` for the turn, the rest from the board at its start. From the rest
 * of a turn (a start not `fresh`), the turn's first basic draw is taken if it was (5.2.7c; WalkBoard.firstDraw).
 */
export function firstState(state: GameState, start: WalkStart, clicks: number, corp: number): WalkState {
  return {
    clicks,
    tags: state.runner.tags,
    grip: state.runner.grip.length,
    stack: state.runner.stack.length,
    drew: start.runnerTurn && !start.fresh && turnFlag(state, TurnFlag.basicDraws) > 0,
    chose: [],
    corp,
    fund: 0,
    ...runCredits(state, start),
    virus: start.virus,
    power: start.power,
    gone: [],
    up: [],
    spike: false,
    mayfly: [],
    bp: 0,
    trashed: [],
    moved: false,
    runs: 0,
  };
}

/** What one turn's search reads besides its targets: the gathered board, the clicks and what they earn, the first state. */
interface TurnInput {
  board: WalkBoard;
  /** runnerEarnings: what the Runner earns with k clicks. */
  earn: number[];
  maxClicks: number;
  /** The first state, its clicks set per split. */
  first: WalkState;
}

/** The turn's input from the board (gathering: the only part of a question that reads `state`). */
function turnInput(state: GameState, start: WalkStart, targets: WalkTarget[], corp: number, from: TurnFrom = nextTurn(state)): TurnInput {
  return { board: walkBoard(state, start, targets), earn: runnerEarnings(state, from), maxClicks: from.clicks, first: firstState(state, start, from.clicks, corp) };
}

/**
 * The least the Runner must bring for one turn through `targets`, in the budget's units (brief 5.5, over the whole turn:
 * a run that ends may be followed by another): over every split of its clicks, the pool the walk needs plus what the
 * clicks it doesn't earn with would have earned (runnerEarnings).
 */
function turnNeed(input: TurnInput, targets: SearchTarget[], memo?: Map<string, number>, retries = false): number {
  return walkNeed(input, new Walk(input.board, targets, memo, retries), targets.length);
}

/**
 * The memos of one question's walks, one per kind (the design answer of 16:29Z, (d)): the single-run walk and the retry
 * walk never share a key, as a single run's value with FAIL at a run's end is not the turn's.
 */
interface WalkMemos {
  one: Map<string, number>;
  turn: Map<string, number>;
}
const walkMemos = (): WalkMemos => ({ one: new Map(), turn: new Map() });

/**
 * The gate (brief rev 2, 3 (a)): whether one Runner turn gets through `targets` within `budget` (`price` added to each
 * walk's need). A single run per target first: if it gets through, so does the turn (a single run is one of its lines),
 * and no retry is asked. Only where it falls short is the retry walk asked, exact (no bound, no cut but the `moved` one).
 */
function passes(input: TurnInput, targets: SearchTarget[], price: number, budget: number, memos: WalkMemos): boolean {
  return turnNeed(input, targets, memos.one) + price <= budget || turnNeed(input, targets, memos.turn, true) + price <= budget;
}

/** turnNeed with its walk made (reachOrders shares a walk's memo with the walks that read the same). */
function walkNeed(input: TurnInput, walk: Walk, runs: number): number {
  const { earn, first } = input;
  const c = Math.max(0, input.maxClicks);
  let need = FAIL;
  for (let e = 0; e + runs <= c; e++) need = Math.min(need, walk.turn({ ...first, clicks: c - e }) + earn[c - 1] - earn[e]);
  return need;
}

/** The Corp's credits through the walk: the rez budget asked, or its credits and every rez it could make (as the oracle). */
export function corpStart(state: GameState, ice: WalkIce[], corpCredits: number): number {
  return Number.isFinite(corpCredits) ? corpCredits : state.corp.credits + ice.filter(c => !c.rezzed).reduce((n, c) => n + c.rezCost, 0);
}

/** The board runBypasses reads for a rez set: the ice rezzed at the walk's start and the set's. */
function bypassBoard(state: GameState, serverId: string, ice: WalkIce[], set: Set<string>): GameState {
  const server = state.corp.servers[serverId];
  return withServerIce(state, serverId, server.ice.map((c, i) => ({ ...c, isRezzed: ice[i].rezzed || set.has(c.instanceId) })));
}

/** A run of the walk's turn on `server` with `set` to rez: its ice as met, and what its bypasses cost (runBypasses; 6.5.8a). */
export function runTarget(state: GameState, base: WalkIce[], server: string, set: Set<string>, clicks = state.runner.maxClicks): { target: WalkTarget; price: number } {
  const all = state.corp.servers[server]?.ice ?? [];
  // The view runBypasses read before (the Runner's clicks but the run's; `clicks`: the turn's, TurnFrom)
  const view: GameState = { ...state, runner: { ...state.runner, clicks: Math.max(0, clicks - 1) } };
  const bypassed = all.length ? runBypasses(bypassBoard(view, server, base, set), server) : undefined;
  const ice = base.map(c => ({ ...c, inS: set.has(c.card.instanceId), bypassed: !!bypassed?.ids.has(c.card.instanceId) }));
  return { target: { server, ice }, price: bypassed?.price ?? 0 };
}

/**
 * One 'runnerTurn' question, gathered (Stage D item 1, the time stop's ruling 4.3): the server's ice as met with no rez
 * set, the board the search reads, and each rez set the Corp can afford (its mask over the ice, its rez cost, the ice its
 * bypasses skip and their price; the empty set always, as `entries` may need it). The search reads this and nothing else,
 * so the question is its own cache key: equal questions are equal answers, whichever board asked.
 */
export interface TurnQuestion extends TurnInput {
  server: string;
  budget: number;
  ice: SearchIce[];
  sets: { mask: number; rez: number; affordable: boolean; bypassed: number; price: number }[];
}

/** A question's answer: the set that holds (its index in `sets`), or the one that asks the most, and its need. */
interface TurnAnswer {
  holds: boolean;
  set: number;
  need: number;
  /** The further runs (sequenceEntries), worked out when first read; the memos are kept for it until then. */
  entries?: number;
  memos?: WalkMemos;
}

/** Answers per decision (ruling 4.3: never across decisions): keyed by the decision's anchor, so they die with it. */
const turnAnswers = new WeakMap<object, Map<string, TurnAnswer>>();
/** Questions asked and searched (the cache's hits are asked less searched), for the time report and its test. */
export const holdCacheStats = { asked: 0, searched: 0 };

/** The question as its key: every value it holds (a non-finite number by name; a Set, Map or function is refused). */
export function questionKey(q: unknown): string {
  return JSON.stringify(q, (_, v) => {
    if (typeof v === 'number' && !Number.isFinite(v)) return `#${v}`;
    if (v instanceof Set || v instanceof Map || typeof v === 'function') throw new Error('hold question: not plain data');
    return v;
  });
}

function turnQuestion(state: GameState, server: string, corpCredits: number, from: TurnFrom, picked?: string[]): TurnQuestion {
  const all = state.corp.servers[server]?.ice ?? [];
  const start = walkStart(state, true, !from.rest, picked);
  const base = turnIce(state, start, server);
  const n = Math.min(all.length, 10);
  const sets: TurnQuestion['sets'] = [];
  for (let mask = 0; mask < 1 << n; mask++) {
    let rez = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) rez = base[i].rezzed ? Infinity : rez + base[i].rezCost;
    // A set with an ice rezzed already is the set without it (its rez cost is no rez's; with the rez budget asked
    // as unlimited, by holdingRez, it was walked again for nothing)
    const affordable = rez < Infinity && rez <= corpCredits;
    if (!affordable && mask) continue;
    const { target, price } = runTarget(state, base, server, new Set(all.slice(0, n).filter((_, i) => mask & (1 << i)).map(c => c.instanceId)), from.clicks);
    const bypassed = target.ice.reduce((m, c, i) => (c.bypassed ? m | (1 << i) : m), 0);
    sets.push({ mask, rez, affordable, bypassed, price });
  }
  // Cheapest first, ties in mask order (as before): the first that holds is the answer
  sets.sort((a, b) => a.rez - b.rez || a.mask - b.mask);
  return {
    ...turnInput(state, start, [{ server, ice: base }], corpStart(state, base, corpCredits), from),
    server,
    budget: runnerBudget(state, from),
    ice: base.map(searchIce),
    sets,
  };
}

/** The run of a question's rez set: the ice as met, the set's ice rezzed as approached and its bypasses skipped. */
function setTarget(q: TurnQuestion, k: number): SearchTarget {
  const { mask, bypassed } = q.sets[k];
  return { server: q.server, ice: q.ice.map((c, i) => ({ ...c, inS: !!(mask & (1 << i)), bypassed: !!(bypassed & (1 << i)) })) };
}

/** The search of a question (pure: it reads `q` alone). */
function solveTurn(q: TurnQuestion): TurnAnswer {
  holdCacheStats.searched++;
  const memos = walkMemos();
  let most = -Infinity;
  let mostSet = -1;
  for (let k = 0; k < q.sets.length; k++) {
    if (!q.sets[k].affordable) continue;
    const target = [setTarget(q, k)];
    // `need` is the single run's (brief rev 2, 2.5); the set holds when no line over the turn gets in within the budget:
    // the gate, then the retry walk only where a single run falls short
    const need = turnNeed(q, target, memos.one) + q.sets[k].price;
    if (need > q.budget && turnNeed(q, target, memos.turn, true) + q.sets[k].price > q.budget) return { holds: true, set: k, need };
    if (need > most) [most, mostSet] = [need, k];
  }
  return { holds: false, set: mostSet < 0 ? q.sets.findIndex(x => x.mask === 0) : mostSet, need: most === -Infinity ? 0 : most, memos };
}

/**
 * `entries` from the run sequence (brief 5.6): the most runs on the server one turn gets in on, against the set that asks
 * the most, failed runs between them allowed (brief rev 2, 2.5: the turn decides `entries`; each check through the gate).
 */
function sequenceEntries(q: TurnQuestion, a: TurnAnswer): number {
  const target = setTarget(q, a.set);
  const { price } = q.sets[a.set];
  const memos = a.memos ?? walkMemos();
  // One run gets in (the set that asks the most does not hold); each further run is walked with the nodes shared
  let k = q.maxClicks > 0 ? 1 : 0;
  while (k < q.maxClicks && passes(q, Array(k + 1).fill(target), (k + 1) * price, q.budget, memos)) k++;
  return k;
}

/**
 * 'runnerTurn' (and 'restOfTurn', from its start) by the walk: the cheapest affordable rez set that keeps the Runner out,
 * or the one that asks the most. Where the turn's end derezzes ice of the Corp's pick (turnEndDerezPicks, a next turn
 * only), the server holds only if it holds for every pick (ruling 8 (a)): the answer is the first pick it does not hold
 * for, else the pick whose holding set costs the most (ties: the least margin).
 */
function walkRunnerTurn(state: GameState, server: string, corpCredits: number, from: TurnFrom = nextTurn(state)): Hold {
  const picks = from.rest ? [undefined] : turnEndDerezPicks(state, [server]);
  if (picks.length === 1) return walkPick(state, server, corpCredits, from, picks[0]);
  // The picks that take the most rez money back first (the likeliest to let the Runner in: the answer stops there)
  const ice = state.corp.servers[server]?.ice ?? [];
  const back = (p: string[]) => ice.reduce((n, c) => n + (p.includes(c.instanceId) ? rezCostOf(state, c) : 0), 0);
  picks.sort((a, b) => back(b!) - back(a!));
  let worst: Hold | undefined;
  for (const picked of picks) {
    const h = walkPick(state, server, corpCredits, from, picked);
    if (!h.holds) return h;
    if (!worst || h.rezCost > worst.rezCost || (h.rezCost === worst.rezCost && h.margin < worst.margin)) worst = h;
  }
  return worst!;
}

/** walkRunnerTurn for one start (one pick of the turn's end derez). */
function walkPick(state: GameState, server: string, corpCredits: number, from: TurnFrom, picked: string[] | undefined): Hold {
  const q = turnQuestion(state, server, corpCredits, from, picked);
  holdCacheStats.asked++;
  const anchor = pricing().anchor;
  let cache = anchor ? turnAnswers.get(anchor) : undefined;
  if (anchor && !cache) turnAnswers.set(anchor, (cache = new Map()));
  const key = cache ? questionKey(q) : '';
  let a = cache?.get(key);
  if (!a) {
    a = solveTurn(q);
    cache?.set(key, a);
  }
  const { budget } = q;
  const { need } = a;
  const ids = (k: number) => q.ice.slice(0, 10).filter((_, i) => q.sets[k].mask & (1 << i)).map(c => c.id);
  if (a.holds) return { holds: true, rez: ids(a.set), rezCost: q.sets[a.set].rez, need, budget, margin: need - budget, entries: 0 };
  // Worked out when read: two readers of the count's many (the ice move, iceCount) read `entries`, and the further runs
  // are most of a count's work (rez money asks every staked server of every board the planner looks at)
  const answer = a;
  return {
    holds: false,
    rez: null,
    rezCost: Infinity,
    need,
    budget,
    margin: need - budget,
    get entries() {
      if (answer.entries === undefined) {
        answer.entries = sequenceEntries(q, answer);
        answer.memos = undefined;
      }
      return answer.entries;
    },
  };
}

/**
 * The run sequence (brief 5.6): whether one Runner turn reaches the breach of each server in `servers` in that order,
 * the Corp rezzing the ice of `rezSets[i]` on run i as it is approached and nothing else: one split of the turn's clicks,
 * the fund filled at each run, the credits hosted on cards and the counters shared, the board carried from run to run
 * (an ice rezzed on one run is met rezzed on the next). `need` is in runnerBudget's units, as serverHold's. Each run's
 * bypasses are priced again (a known gap: a counter one bypass spends is not taken from the next).
 * A test and script entry point (the brute-force reference, scripts/stage-d): no reader in src; keepFor reads
 * reachQuestion and reachSets, which answer the same.
 */
export function turnReach(state: GameState, servers: string[], rezSets: string[][], corpCredits = state.corp.credits): { reaches: boolean; need: number; budget: number } {
  // The turn's end derez of the Corp's pick (ruling 8 (a)): reached if some pick lets the Runner in; `need` the least
  const ways = turnEndDerezPicks(state, servers).map(picked => reachPick(state, servers, rezSets, corpCredits, picked));
  return ways.reduce((a, b) => ({ reaches: a.reaches || b.reaches, need: Math.min(a.need, b.need), budget: a.budget }));
}

/** turnReach for one pick of the turn's end derez. */
function reachPick(state: GameState, servers: string[], rezSets: string[][], corpCredits: number, picked: string[]): { reaches: boolean; need: number; budget: number } {
  return counted(() => {
    const budget = runnerBudget(state);
    if (!servers.length) return { reaches: true, need: 0, budget };
    const start = walkStart(state, true, true, picked);
    const bases = new Map<string, WalkIce[]>();
    const baseOf = (id: string) => bases.get(id) ?? bases.set(id, turnIce(state, start, id)).get(id)!;
    const runs = servers.map((id, i) => runTarget(state, baseOf(id), id, new Set(rezSets[i] ?? [])));
    const corp = corpStart(state, [...bases.values()].flat(), corpCredits);
    const targets = runs.map(r => r.target).map(searchTarget);
    const input = turnInput(state, start, runs.map(r => r.target), corp);
    const price = runs.reduce((n, r) => n + r.price, 0);
    const memos = walkMemos();
    // `need` is the single runs' (as serverHold's); `reaches` is the turn's, through the gate
    const need = turnNeed(input, targets, memos.one) + price;
    return { reaches: need <= budget || passes(input, targets, price, budget, memos), need, budget };
  });
}

/**
 * The run sequence over a list of servers, gathered once (the 14:39Z ruling on keepFor's time): the walk's start, each
 * server's ice as met with nothing more rezzed and its bypasses' price, the earnings, the first state, and the board for
 * all of them (break plans and subtypes are keyed by ice, so a server outside an order is never read), with each ice as a
 * lender both ways (a borrow lends from the walked ice as met and the rest as the board has it, so the lenders depend on
 * which servers an order runs). `reachOrder` answers turnReach(state, order, no rezzes) from it and nothing else.
 */
export interface ReachQuestion extends TurnInput {
  budget: number;
  targets: Record<string, SearchTarget>;
  prices: Record<string, number>;
  /** Whether a server's ice borrows (walkBoard's rule: then the lenders are gathered). */
  borrows: Record<string, boolean>;
  views: { id: string; server: string | null; walked?: Lender; unwalked?: Lender }[];
  /** The same question from the other picks of the turn's end derez (turnEndDerezPicks, ruling 8 (a)): a set or an order is reached if some pick reaches it. */
  others?: ReachQuestion[];
}

/** The question for `servers` (the Corp's credits as they are; corpStart with a finite budget is that budget), from `from` (TurnFrom; the rest of a turn asks it of afterRun's board). */
export function reachQuestion(state: GameState, servers: string[], from: TurnFrom = nextTurn(state)): ReachQuestion {
  const [first, ...rest] = from.rest ? [undefined] : turnEndDerezPicks(state, servers);
  const q = reachPickQuestion(state, servers, from, first);
  return rest.length ? { ...q, others: rest.map(picked => reachPickQuestion(state, servers, from, picked)) } : q;
}

/** reachQuestion for one pick of the turn's end derez. */
function reachPickQuestion(state: GameState, servers: string[], from: TurnFrom, picked: string[] | undefined): ReachQuestion {
  return counted(() => {
    const start = walkStart(state, true, !from.rest, picked);
    const runs = servers.map(id => runTarget(state, turnIce(state, start, id), id, new Set(), from.clicks));
    const targets = runs.map(r => r.target);
    const input = turnInput(state, start, targets, state.corp.credits, from);
    const walked = new Map(targets.flatMap(t => t.ice.map(x => [x.id, x] as const)));
    const serverOf = new Map(targets.flatMap(t => t.ice.map(x => [x.id, t.server] as const)));
    const borrows = Object.fromEntries(targets.map(t => [t.server, t.ice.some(i => i.subs.some(f => f.does.some(e => e.kind === 'borrow')))]));
    // The lenders are read only by a borrow (setInput, walkBoard's rule)
    const views = Object.values(borrows).some(Boolean) ? lenderViews(state, walked) : [];
    // Nothing is rezzed on these runs (6.4.3: only a rez set's ice is rezzed as approached), so the Corp's credits are
    // read only by a subroutine's "more credits than the Runner", and HQ's size only by "more cards in HQ than in the
    // grip" and "trash 1 card from HQ to end the run": where no subroutine of these servers or of a lender says so, they
    // are left out of the question (0), so that boards differing in them alone ask the same
    const facts = [...targets.flatMap(t => t.ice.flatMap(i => (i.rezGains ? [...i.subs, i.rezGains] : i.subs))), ...views.flatMap(v => [...(v.walked?.facts ?? []), ...(v.unwalked?.facts ?? [])])];
    const ifs = facts.flatMap(f => f.does.map(e => (e.kind === 'endRun' ? e.if?.kind : e.kind)));
    const corpRead = ifs.includes('corpCreditsMoreThanRunner');
    const hqRead = ifs.includes('hqMoreThanGrip') || ifs.includes('corpMayTrashHqToEndRun');
    return {
      ...input,
      first: corpRead ? input.first : { ...input.first, corp: 0 },
      board: { ...input.board, lenders: [], hq: hqRead ? input.board.hq : 0 },
      budget: runnerBudget(state, from),
      targets: Object.fromEntries(targets.map(t => [t.server, searchTarget(t)])),
      prices: Object.fromEntries(runs.map(r => [r.target.server, r.price])),
      borrows,
      views: views.map(v => ({ ...v, server: serverOf.get(v.id) ?? null })),
    };
  });
}

/** The board of the orders of a set of servers: the lenders a borrow reads when those servers are walked. */
function setInput(q: ReachQuestion, set: string[]): TurnInput {
  const on = new Set(set);
  const lenders = set.some(id => q.borrows[id]) ? q.views.flatMap(v => (v.server !== null && on.has(v.server) ? [v.walked!] : v.unwalked ? [v.unwalked] : [])) : [];
  return { ...q, board: { ...q.board, lenders } };
}

/** Whether one Runner turn gets through `order`'s servers in that order, through the gate (its memos given or its own). */
const reaches = (q: ReachQuestion, order: string[], input: TurnInput, memos = walkMemos()): boolean =>
  passes(input, order.map(id => q.targets[id]), order.reduce((n, id) => n + q.prices[id], 0), q.budget, memos);

/**
 * turnReach(state, order, no rezzes) from the gathered question, its own memo (pure: it reads `q` alone). A test and
 * script entry point: no reader in src (reachSets is keepFor's).
 */
export function reachOrder(q: ReachQuestion, order: string[]): boolean {
  return !order.length || reaches(q, order, setInput(q, order)) || !!q.others?.some(o => reachOrder(o, order));
}

/** Every order of `ids`. */
export const orders = (ids: string[]): string[][] => (ids.length <= 1 ? [ids] : ids.flatMap((id, i) => orders([...ids.slice(0, i), ...ids.slice(i + 1)]).map(rest => [id, ...rest])));

/**
 * The answers per decision (as turnAnswers: on the decision's anchor, never across decisions). An order's answer reads
 * the question's common part (the board but its break plans and lenders, the earnings, the clicks, the first state, the
 * budget, the lenders as the board has them) and the part of each server it runs (its ice as met, the price of its
 * bypasses, whether it borrows, its ice as walked lenders, its ice's plans and subtypes): each part is interned, and an
 * answer is keyed by the common part and the parts it runs, so the questions a decision asks (the staked servers of
 * each board it looks at, with or without a line's agenda) share what they have in common. A set's answer (some order
 * reaches it) is keyed by the common part and its parts. The walks' memos are shared by the orders of one question and
 * set (their node keys name servers, which a question fixes; the set fixes what a node reads besides its key).
 */
interface ReachCache {
  ids: Map<string, number>;
  orders: Map<string, boolean>;
  sets: Map<string, boolean>;
  memos: Map<string, WalkMemos>;
}
const reachAnswers = new WeakMap<object, ReachCache>();

/** Whether some order of a set of the question's servers is reached (reachOrder), cached per decision (above); with picks (`others`), by some pick. */
export function reachSets(q: ReachQuestion): (set: string[]) => boolean {
  if (q.others) {
    const each = [q, ...q.others].map(x => reachSetsOf({ ...x, others: undefined }));
    return set => each.some(f => f(set));
  }
  return reachSetsOf(q);
}

function reachSetsOf(q: ReachQuestion): (set: string[]) => boolean {
  const anchor = pricing().anchor;
  let c = anchor ? reachAnswers.get(anchor) : undefined;
  if (!c) {
    c = { ids: new Map(), orders: new Map(), sets: new Map(), memos: new Map() };
    if (anchor) reachAnswers.set(anchor, c);
  }
  const cache = c;
  const intern = (x: unknown) => {
    const k = questionKey(x);
    let id = cache.ids.get(k);
    if (id === undefined) cache.ids.set(k, (id = cache.ids.size));
    return id;
  };
  const common = intern({
    board: { ...q.board, plans: {}, types: {}, lenders: [] },
    earn: q.earn,
    maxClicks: q.maxClicks,
    first: q.first,
    budget: q.budget,
    unwalked: q.views.map(v => v.unwalked ?? null),
  });
  const part: Record<string, number> = {};
  for (const [id, t] of Object.entries(q.targets)) {
    const own = (k: string) => t.ice.some(i => k.startsWith(`${i.id}|`));
    part[id] = intern({
      target: t,
      price: q.prices[id],
      borrows: q.borrows[id],
      walked: q.views.filter(v => v.server === id).map(v => v.walked),
      plans: Object.entries(q.board.plans).filter(([k]) => own(k)),
      types: Object.entries(q.board.types).filter(([k]) => own(k)),
    });
  }
  const servers = `${common}|${Object.keys(q.targets).map(id => `${id}=${part[id]}`)}`;
  return set => {
    if (!set.length) return true;
    const sk = `${common}|${set.map(id => part[id]).sort((a, b) => a - b)}`;
    let a = cache.sets.get(sk);
    if (a !== undefined) return a;
    // One board and one memo for the set's orders: the lenders and the walk's options read the set, not its order
    const input = setInput(q, set);
    const mk = `${servers}|${[...set].sort()}`;
    let memo = cache.memos.get(mk);
    if (!memo) cache.memos.set(mk, (memo = walkMemos()));
    a = orders(set).some(order => {
      const k = `${common}|${order.map(id => part[id])}`;
      let r = cache.orders.get(k);
      if (r === undefined) cache.orders.set(k, (r = reaches(q, order, input, memo)));
      return r;
    });
    cache.sets.set(sk, a);
    return a;
  };
}

/** 'thisRun' by the walk: from the approached ice at `from`, the Runner's credits and clicks as they are. */
function walkThisRun(state: GameState, server: string, opts: HoldOptions): Hold {
  const run = state.activeRun;
  const sv = state.corp.servers[server];
  // The Runner's credits, and on its turn what its hosted counters pay with no click (counterCredits; 6.9.3b: a paid
  // ability's window during the run)
  const rig = [...state.runner.rig.programs, ...state.runner.rig.hardware, ...state.runner.rig.resources];
  const budget = state.runner.credits + (state.activePlayer === 'runner' ? rig.reduce((n, c) => n + counterCredits(c), 0) : 0);
  const none: Hold = { holds: false, rez: null, rezCost: Infinity, need: 0, budget, margin: -budget, entries: 1 };
  const pos = opts.from ?? run?.icePosition ?? null;
  if (!run || !sv || pos === null) return none;
  const credits = opts.corpCredits ?? state.corp.credits;
  const must = sv.ice.filter(c => opts.mustRez?.includes(c.instanceId));
  const base = must.reduce((n, c) => n + rezCost(state, c), 0);
  // As before (Stage B2): the approached ice may be rezzable for less than its printed cost (Biawak's forfeit)
  const paidAnotherWay = base > credits && must.length > 0 && must.every(c => c.instanceId === sv.ice[run.icePosition ?? -1]?.instanceId && isLegalAction(state, { type: 'REZ_CARD', player: 'corp', cardInstanceId: c.instanceId }));
  if (base > credits && !paidAnotherWay) return none;
  const spare = paidAnotherWay ? 0 : credits - base;
  const open = (opts.further ?? true) ? sv.ice.slice(0, pos).filter(c => !c.isRezzed).slice(0, 10) : [];
  const start = walkStart(state, false);
  const ice0 = walkIce(state, start, sv.ice);
  const board = walkBoard(state, start, [{ server, ice: ice0 }]);
  let best = Infinity;
  let bestSet: string[] | null = null;
  let bestNeed = 0;
  let mostNeed = -Infinity;
  for (let mask = 0; mask < 1 << open.length; mask++) {
    const extra = open.filter((_, i) => mask & (1 << i));
    const cost = base + extra.reduce((n, c) => n + rezCost(state, c), 0);
    if (cost - base > spare || cost >= best) continue;
    const up = new Set([...must.map(c => c.instanceId), ...extra.map(c => c.instanceId)]);
    const view = withServerIce(state, sv.id, sv.ice.map(c => (up.has(c.instanceId) ? { ...c, isRezzed: true } : c)));
    const skipped = bypassesAhead(view, view.corp.servers[sv.id].ice.slice(0, pos + 1), true);
    const ice = ice0.map(c => ({ ...searchIce(c), inS: up.has(c.id), bypassed: skipped.has(c.id) }));
    // The Corp pays each rez as its ice is approached (6.4.3): it starts with the approached ice's cost still in hand
    const corp = spare + base;
    // The run's own credits: the fund and Overclock's; the cards that pay during it are the first state's (runCredits)
    const fund = run.bonusCredits + (run.badPublicityCredits ?? 0);
    const ws: WalkState = { ...firstState(state, start, state.runner.clicks, corp), fund };
    const need = new Walk(board, [{ server, ice }], undefined, false).fromIce(ws, pos);
    if (need > mostNeed) mostNeed = need;
    if (need > budget) {
      best = cost;
      bestSet = [...up];
      bestNeed = need;
    }
  }
  if (bestSet) return { holds: true, rez: bestSet, rezCost: best, need: bestNeed, budget, margin: bestNeed - budget, entries: 0 };
  const need = mostNeed === -Infinity ? 0 : mostNeed;
  return { ...none, need, margin: need - budget };
}
import { CardInstance, GameState, cardDef, getCardScript, isLegalAction, rezCostOf, availableCredits } from '../../core';
import { rezCost, stealthCredits, threatLevel, TurnFlag, turnFlag } from '../../core/engine/cardEffects';
import { canBreakSubroutinesWith, iceScript, iceSubroutines, iceSubtypes, isBioroid } from '../../core/engine/ice';
import { SubEffect, SubFacts, bioroidBreakClicks, breakPlans, bypassesAhead, plannedSubroutines, runBypasses, subroutineFacts } from '../runs';
import { CARDS, clickMoneyOf, turnIncomeOf } from '../cards';
import type { HoldFacts } from '../cards/types';
import { counters } from '../../core/engine/cardEffects';
import { plan, pricing, withPricing } from '../pricing';
import { memo } from '../valueModel';

/**
 * Owner: does a server hold (Step 4 Stage A, spec-step4-corp-core.md 1.4; registry row "what holds a server").
 *
 * One function, serverHold, answers for the horizons the Corp counts today:
 *  - 'runnerTurn': can the Runner get in on its next turn, against the cheapest set of ice the Corp can afford to rez
 *    (holdCost's count, moved here from countedScore.ts);
 *  - 'restOfTurn' (Stage D item 3, F1): the same walk from a different start, the rest of the Runner's turn under way
 *    once its run is over (TurnFrom: the clicks it has left, the credits it is left with, no turn-start money or
 *    counters again, its first draw of the turn taken if it was): what rez money keeps for the rest of this turn;
 *  - 'thisRun': can the Runner get through the rest of the run under way with its credits now (stopCost's count, moved
 *    here from rezModel.ts).
 * The Corp rezzes ice as it is approached (rules 3.4.3a, 6.4.3, 6.9.2b); unrezzed ice is passed (6.9.2c); a bypassed
 * ice's subroutines never resolve (6.5.8a-b). Capability from public facts, not our Runner AI's choice; no Runner grip
 * and no deck order is read (10.2.2a).
 *
 * Both horizons are answered by one walk of the Runner's turn (Stage D item 1, below: "The walk"), from the same facts;
 * they differ in the Runner's budget, where the walk starts, and how many runs it may make. `margin` and `entries` are
 * read by the ordinary moves (candidates.ts, placement.ts) as sort keys and by the ice move's fall.
 */

export interface HoldOptions {
  /**
   * 'runnerTurn' (the Runner's next turn, runnerBudget), 'thisRun' (the run under way, the Runner's credits now) or
   * 'restOfTurn' (the rest of the Runner's turn under way once its run is over, runnerBudget of restOfTurn).
   */
  when: 'runnerTurn' | 'thisRun' | 'restOfTurn';
  /** The credits the Corp may spend on rezzes ('thisRun' defaults to its credits now). */
  corpCredits?: number;
  /** 'restOfTurn': the Runner's credits once the run under way is over (default its credits now). */
  runnerCredits?: number;
  /** 'thisRun': the approached ice's position (default the run's icePosition); the ice from it inward is counted. */
  from?: number;
  /** 'thisRun': ice that must be rezzed (the approached ice, priced at its rez cost; stopCost's `ice`). */
  mustRez?: string[];
  /** 'thisRun': whether the unrezzed ice further in may be rezzed too (stopCost's `further`; default true). */
  further?: boolean;
}

export interface Hold {
  /**
   * Some affordable rez set keeps the Runner out ('runnerTurn': over its whole turn, a run that fails followed by another;
   * 'thisRun': the run under way).
   */
  holds: boolean;
  /** The cheapest holding rez set (instance ids of the ice to rez), or null when none holds. */
  rez: string[] | null;
  /** Its rez spend; Infinity when none holds. */
  rezCost: number;
  /**
   * The Runner's credit need for a single run ('runnerTurn': one run, its clicks split between earning and the run, as
   * before the failed run was counted) against the holding set, or against the affordable set that asks the most (on
   * this one-run need) when none holds. A second run after a failed one can get in where this need is above the budget:
   * then `holds` is false and `margin` above 0 (the brief rev 2, 2.5).
   */
  need: number;
  /** The most the Runner can bring: runnerBudget ('runnerTurn', 'restOfTurn' from its start) or its credits now ('thisRun'). */
  budget: number;
  /** need - budget: above 0 when it holds; above 0 with `holds` false where only a run after a failed one gets in. */
  margin: number;
  /**
   * How many runs on the server one Runner turn gets in on ('runnerTurn': the run sequence of sequenceEntries against
   * the set that asks the most, each run walked with the board the runs before it left, failed runs between them
   * allowed; at least 1 when it does not hold; 'thisRun': 1 or 0). 0 when it holds.
   */
  entries: number;
}

/** Sensitivity knob for the stage 0 report: extra credits granted to the Runner's run (an economy event from the grip it may hold). */
export const CHECK = { runnerExtra: 0 };

/**
 * The Runner's budget for one run on its next turn, from public facts: its credits, and what its installed cards and
 * every click but the run's make (runnerMoney: card entries, never the grip; 5.2.7a). Count inputs F2: before it, 1
 * credit a click, so a loaded Telework Contract was missed (paired +0.0 ± 0.4 at games=3, run 42918973725).
 */
export const runnerBudget = (s: GameState, from: TurnFrom = nextTurn(s)): number => from.credits + runnerEarnings(s, from)[Math.max(0, from.clicks - 1)] + CHECK.runnerExtra;

/**
 * Where a turn's walk starts (Stage D item 3, F1). The Runner's next turn (`rest` false): its turn begins (5.7.1: the
 * turn-start money and counters), every click (maxClicks), its credits now. The rest of the turn under way once its run
 * is over (`rest` true): the clicks it has left, the credits it is left with (`credits`), nothing of the turn's start
 * again; a once-per-turn click ability already used this turn is counted again (toward a richer Runner).
 */
export interface TurnFrom {
  rest: boolean;
  clicks: number;
  credits: number;
}
export const nextTurn = (s: GameState): TurnFrom => ({ rest: false, clicks: Math.max(0, s.runner.maxClicks), credits: s.runner.credits });
export const restOfTurn = (s: GameState, credits = s.runner.credits): TurnFrom => ({ rest: true, clicks: Math.max(0, s.runner.clicks), credits });

const hosted = (c: CardInstance) => counters(c, 'credit');

/**
 * The credits the Runner's installed cards and its clicks but the run's make on its next turn: each installed card's
 * turn-start payment (no more than it holds), then the best set of its paying click abilities (one use each: Telework
 * Contract is once per turn, Fermenter and Rent Rioters are trashed, Pennyshaver pays 1 after its first use), the
 * other clicks 1 credit each (5.2.7a).
 */
export function runnerMoney(s: GameState): number {
  return runnerEarnings(s)[Math.max(0, s.runner.maxClicks - 1)];
}

/**
 * What k earning clicks make on the Runner's next turn, for k = 0 .. maxClicks (runnerMoney is k = maxClicks - 1): each
 * installed card's turn-start payment (no more than it holds), then the best set of its paying click abilities within
 * the k clicks (one use each), the other clicks 1 credit each (5.2.7a). The hold walk splits the turn's clicks between
 * earning and the rest (brief 5.3) and reads this for both. From the rest of a turn (`from.rest`): k = 0 .. its clicks left,
 * with no turn-start payment or turn-start counter (paid or placed already this turn).
 */
export function runnerEarnings(s: GameState, from: TurnFrom = nextTurn(s)): number[] {
  const rig = [...s.runner.rig.programs, ...s.runner.rig.hardware, ...s.runner.rig.resources];
  let drip = 0;
  const uses: { clicks: number; credits: number }[] = [];
  for (const c of rig) {
    const pay = turnIncomeOf(c.cardCode);
    if (pay && !from.rest) drip += pay.hosted ? Math.min(pay.credits, hosted(c)) : pay.credits;
    const m = clickMoneyOf(c.cardCode);
    if (!m) continue;
    let credits = m.credits;
    if (m.hosted === 'cap') credits = Math.min(credits, hosted(c));
    if (m.hosted === 'add') credits += hosted(c);
    if (m.perVirus) credits += m.perVirus.credits * (counters(c, 'virus') + (from.rest ? 0 : m.perVirus.turnStart));
    if (credits > m.clicks) uses.push({ clicks: m.clicks, credits });
  }
  const max = from.clicks;
  const n = Math.min(uses.length, 10);
  const out: number[] = [];
  for (let clicks = 0; clicks <= max; clicks++) {
    let best = clicks;
    for (let mask = 1; mask < 1 << n; mask++) {
      let k = 0;
      let got = 0;
      for (let i = 0; i < n; i++) if (mask & (1 << i)) {
        k += uses[i].clicks;
        got += uses[i].credits;
      }
      if (k <= clicks) best = Math.max(best, got + clicks - k);
    }
    out.push(drip + best);
  }
  return out;
}

/** Does the server hold, and by how much (see the file comment)? */
export function serverHold(state: GameState, server: string, opts: HoldOptions): Hold {
  if (opts.when === 'thisRun') return walkThisRun(state, server, opts);
  if (opts.when === 'restOfTurn') {
    const board = afterRun(state);
    return counted(() => walkRunnerTurn(board, server, opts.corpCredits ?? state.corp.credits, restOfTurn(board, opts.runnerCredits)));
  }
  return counted(() => walkRunnerTurn(state, server, opts.corpCredits ?? state.corp.credits));
}

/**
 * The board of the rest of the turn: the run under way over (its once-per-run uses and run flags gone, 6.8.5, 6.9.6d:
 * the run's rez cost increase among them, which rezCost adds to every ice), once per board on valueModel's memo (dropped
 * when the board is changed in place), so the memos keyed on it (turnIce, the break plans) serve every ask at one rez
 * window.
 */
export function afterRun(state: GameState): GameState {
  return state.activeRun ? memo(state, 'afterRun', () => ({ ...state, activeRun: null })) : state;
}

/** Counted with countingHold up: the rez budget its prices reach does not ask this count again (deal 2138's hang). */
const counted = <T>(f: () => T): T => (pricing().countingHold ? f() : withPricing({ countingHold: true }, f));

/** A copy-free view with this one ice standing in for its unrezzed self (iceCreditNeed reads the board for strength). */
function withIce(state: GameState, ice: CardInstance): GameState {
  const server = Object.values(state.corp.servers).find(v => v.ice.some(c => c.instanceId === ice.instanceId));
  if (!server) return state;
  return { ...state, corp: { ...state.corp, servers: { ...state.corp.servers, [server.id]: { ...server, ice: server.ice.map(c => (c.instanceId === ice.instanceId ? ice : c)) } } } };
}

const withServerIce = (state: GameState, id: string, ice: CardInstance[]): GameState => ({ ...state, corp: { ...state.corp, servers: { ...state.corp.servers, [id]: { ...state.corp.servers[id], ice } } } });

// =====================================================================================================================
// The walk (Stage D item 1 branch 2, brief rev 2 section 5): the count as a model of the Runner's turn
// =====================================================================================================================
//
// With a rez set S, the Runner's turn is walked from public facts (10.2.2): for 'runnerTurn' from the board at its turn
// start (5.7.1: Botulus and Tranquilizer counters placed, Tranquilizer's and Lycian's derez), its clicks split between
// earning (runnerEarnings), the run and the clicks the run spends; for 'thisRun' from the run under way. The run meets
// the ice outermost first (6.9.2): unrezzed ice outside S is passed (6.9.2c), ice of S is rezzed as it is approached
// (6.4.3) and its rez-time facts apply (Flyswatter's purge), bypassed ice is skipped (6.5.8a, runBypasses as before).
// At each rezzed ice the Runner chooses which subroutines to break and how (a break plan from breakPlans, Botulus's
// counters, the ice's own click or credit ability), and the rest resolve in printed order against the state the walk
// carries (9.8.7b). Clicks, counters, grip cards and once-a-run uses are shared along the run (1.16.1: a cost is paid in
// full). The walk carries facts, never worths (ruling 5): it reads subroutineFacts, the card entries' holdFacts and
// breakPlans' credits and spends, and calls no price.
//
// The failed run (Stage D item 1 follow-up 1, brief rev 2 section 2). On the Runner's turn a run that ends before its
// breach (6.1.4) is not the end of the turn: the turn goes on from the state the run left and the target may be run
// again while clicks remain (the truth of `holds` is the whole turn: Ping's tag cleared before a second run,
// Thunderbolt's gained subroutine gone with its run). The Runner may let a run end on purpose (an ending subroutine left
// unbroken, an ending toll taken). What stays: the ice the Corp rezzed (their rez-time facts not repeated), the Corp's
// credits and lasting choices (Lycian's subtypes), an ice that trashed itself, the Runner's tags, grip, stack, counters,
// trashed cards and hosted credits. What ends with the run (6.8.5, 6.9.6d): the bad publicity fund (10.6.3b, 6.9.6b),
// Mayfly, Pressure Spike's use, the subroutine a rez gave for the run (Thunderbolt; 9.8.3e is where it sits). It is
// asked behind a gate (passes): only of a rez set a single run does not get through, so `need` and `margin` stay the
// single run's. Not counted (each errs as said):
//  - "X or end the run" is taken as the end (ruling 6; 1.14.5: the Corp chooses), so a stronger X (Ballista's program
//    trash, not modelled) is missed: toward "does not hold" (registry debt);
//  - the rez set is fixed and each ice of it is rezzed on the first run that approaches it with the Corp able to pay;
//    the Corp may decline a rez on the first run and make it on the second (6.4.3): toward "does not hold";
//  - Tatu-Bola's swap after it is passed (the Corp 4 richer, an unknown ice met on the next run): toward "does not hold";
//  - over several servers, a failed run on one server made only to drain the Corp for another is not walked (the Corp
//    may decline that rez; the fixed set cannot say so): a retry is on the same target, before the next one.
//
// The pool is not carried: each node works out the least credits in the Runner's pool that get it through from there
// (every effect on the pool is monotone: a payment adds, a condition sets a floor, a loss of n adds n above 0). So one
// pass answers the least the Runner must bring, for every click split, with no search over the credits.

/** No way through. */
const FAIL = Infinity;

/** The pool needed before losing n credits from it, `after` needed after (a loss takes no more than the pool holds). */
const lose = (after: number, n: number): number => (after > 0 ? after + n : 0);

/** A piece of ice as the walk meets it. */
export interface WalkIce {
  /** The ice, rezzed: the subroutines and subtypes it is met with (gathered; the search reads only `id`). */
  card: CardInstance;
  id: string;
  /** Rezzed when the walk starts (the Runner's turn start applied). */
  rezzed: boolean;
  rezCost: number;
  /** In the rez set: the Corp rezzes it as it is approached (6.4.3). */
  inS: boolean;
  /** Skipped by the Runner's bypasses (runBypasses, bypassesAhead; 6.5.8a). */
  bypassed: boolean;
  subs: SubFacts[];
  types: string[];
  /** Rig indexes of the Botulus programs it hosts ("Hosted virus counter: Break 1 subroutine on host ice"). */
  botulus: number[];
  /** Hosted cards that bypass it for credits (Physarum Entangler): rig index, credits a subroutine, the subtype it can't bypass. */
  bypassers: { idx: number; per: number; unless: string }[];
  /** Its own break ability for credits ("3 credits: Break 1 subroutine on this ice", N-Pot). */
  selfCredits?: number;
  /** A bioroid: the Runner may break its subroutines with clicks (bioroidBreakClicks, by the number broken). */
  bioroid: boolean;
  breakClicks: number[];
  /** Botulus may break its subroutines (not Semak-samun's fracters-only). */
  anyBreaker: boolean;
  rezFacts?: HoldFacts['rezDuringRun'];
  /** What the Runner meets as the encounter begins (6.9.3a: Funhouse, Seraph, Jaguarundi; Paywall). */
  encounterFacts?: HoldFacts['encounter'];
  /** Rig indexes of the hosted cards that give it subtypes (Chromatophores): a Corp trash of one changes them. */
  granters: number[];
  /** 'thisRun': the encounter with it is under way; the subroutines already broken. */
  broken?: boolean[];
  /** The subroutine it gains after its others when the Corp rezzes it during a run (Thunderbolt Armaments, 9.8.3e; its +1 strength is not modelled, the todo in tests/holdWalk.test.ts). */
  rezGains?: SubFacts;
  /** Its rez costs the Corp 1 bad publicity or the Runner 1 tag, the Corp's choice (holdFacts.rezBadPublicityOrTag). */
  liability: boolean;
  /** Unrezzed at the walk's start, and the Corp chooses its subtypes when it rezzes it (holdFacts.rezChoosesSubtypes, Lycian): the sets it may choose. `types` is then without a choice. */
  choices?: string[][];
}

/** One run of the walk's turn: its server and its ice, innermost first (as the server lists them). */
export interface WalkTarget {
  server: string;
  ice: WalkIce[];
}

/** The ice as the search reads it: no card, so nothing of the board but what was gathered. */
export type SearchIce = Omit<WalkIce, 'card'>;
export interface SearchTarget {
  server: string;
  ice: SearchIce[];
}
export const searchTarget = (t: WalkTarget): SearchTarget => ({ server: t.server, ice: t.ice.map(searchIce) });
function searchIce(w: WalkIce): SearchIce {
  const out: Partial<WalkIce> = { ...w };
  delete out.card;
  return out as SearchIce;
}

/** What the rig's cards are to the search. */
export interface RigFacts {
  /** A trojan (Bumi 1.0 may trash it). */
  trojan: boolean;
  /** Trashed by a purge (Physarum Entangler). */
  purgeTrash: boolean;
  /** A breaker or Botulus: its counters are read (memo key). */
  counted: boolean;
}

/**
 * Everything the search reads besides its targets and its state, gathered from the board once per question (Stage D
 * item 1, the time stop's ruling 4.3: a pure search, so the gathered question is its own cache key). Break plans and
 * subtypes are gathered for every number of subroutines and every set of the hosted cards that give subtypes gone.
 */
export interface WalkBoard {
  badPublicity: number;
  threat: number;
  hq: number;
  tags: number;
  grip: number;
  rig: RigFacts[];
  lenders: Lender[];
  /** `${ice id}|${subroutines to break}|${granters gone}|${the Corp's choice of subtypes at rez, by index, or ''}`. */
  plans: Record<string, WalkPlan[]>;
  /** `${ice id}|${granters gone}|${choice}` (some gone, or a choice made). */
  types: Record<string, string[]>;
  /** plan.bypass: the Runner's own bypasses (Physarum Entangler) are tried. */
  bypass: boolean;
  /** The cards the turn's first basic draw gives (Verbal Plasticity: "The first time each turn you take the basic action to draw 1 card, instead draw 2 cards"; the engine's firstBasicDraw); 1 without one. */
  firstDraw: number;
}

/** The state the walk carries (brief 5.1), but the Runner's pool: the walk works out the least pool a way needs. */
export interface WalkState {
  clicks: number;
  tags: number;
  grip: number;
  stack: number;
  /** The turn's first basic draw is taken (WalkBoard.firstDraw). */
  drew: boolean;
  /** The Corp's subtype choices for ice rezzed during the walk (`${ice id}:${index into choices}`, sorted; Lycian). */
  chose: string[];
  corp: number;
  /** Credits the Runner can spend only during this run (the bad publicity fund, filled at each run's start, 10.6.3a-b; Overclock's). */
  fund: number;
  /** Bad publicity the Corp took during the walk (a liability rez): in the fund from the next run on (10.6.3c). */
  bp: number;
  /** Credits on cards that pay during runs (runCredits: no stealth card's), any cost but a stealth part: shared through the turn. */
  hosted: number;
  /** Credits on stealth cards (runCredits): a plan's stealth part, and any other cost during a run too. */
  stealth: number;
  /** Counters on each rig card (by rig index). */
  virus: number[];
  power: number[];
  /** Rig indexes trashed during the walk. */
  gone: number[];
  /** Ice rezzed during the walk. */
  up: string[];
  /** Pressure Spike's once-a-run boost used this run. */
  spike: boolean;
  /** Rig indexes trashed when the run ends (Mayfly). */
  mayfly: number[];
  /** Ice that trashed itself during the walk ("Trash this ice"): gone for the rest of the turn. */
  trashed: string[];
  /** This run changed something a later run reads in the Runner's favour (Walk.ended has the list). */
  moved: boolean;
}

/** A break plan as the walk spends it: breakPlans' credits and its spends, by rig index. */
export interface WalkPlan {
  breaker: number;
  credits: number;
  stealth: number;
  counter?: { idx: number; kind: 'virus' | 'power'; n: number };
  grip: number;
  mayfly: boolean;
  spike: boolean;
}

/** What the walk does not carry (trashing or bouncing a Runner card, the Corp's own side, a jack out it may take). */
const INERT = new Set<SubEffect['kind']>(['trashInstalled', 'toGrip', 'iceStrengthThisRun', 'corpSide', 'mayJackOut', 'unknown']);
/** A subroutine that changes nothing the walk carries: breaking it never helps, so the walk leaves it to resolve. */
const inert = (f: SubFacts) => !f.orEndRun && f.does.every(e => INERT.has(e.kind));

/** A subroutine whose resolution ends the run whatever the state ("End the run.", "X or end the run": ruling 6). */
const alwaysEnds = (f: SubFacts) => !f.when && !f.unless && (f.orEndRun || f.does.some(e => e.kind === 'endRun' && !e.if));

/** The board the walk starts from: the rig, its counters, and the ice derezzed by then (brief 5.2). */
export interface WalkStart {
  rig: CardInstance[];
  index: Map<string, number>;
  virus: number[];
  power: number[];
  derezzed: Set<string>;
  /** 'runnerTurn': the Runner's next turn (a run under way is not part of it). */
  runnerTurn: boolean;
  /** A turn's start (5.7.1) comes first: its counters placed, Lycian derezzed; false for the rest of a turn under way. */
  fresh: boolean;
}

/** The walk's start: the run under way (`runnerTurn` false), the Runner's next turn, or (`fresh` false) the rest of this turn. */
export function walkStart(state: GameState, runnerTurn: boolean, fresh = runnerTurn): WalkStart {
  const rig = [...state.runner.rig.programs, ...state.runner.rig.hardware, ...state.runner.rig.resources];
  const index = new Map(rig.map((c, i) => [c.instanceId, i]));
  const virus = rig.map(c => counters(c, 'virus'));
  const power = rig.map(c => counters(c, 'power'));
  const derezzed = new Set<string>();
  if (runnerTurn && fresh) {
    // When a turn ends, Lycian Multi-Munition derezzes itself: by the Runner's next turn it is unrezzed
    for (const sv of Object.values(state.corp.servers)) for (const c of sv.ice) if (c.isRezzed && CARDS[c.cardCode]?.holdFacts?.turnEndDerezSelf) derezzed.add(c.instanceId);
    // 5.7.1d: the Runner's turn begins: Botulus and Tranquilizer place a counter, then Tranquilizer derezzes its host at 3
    rig.forEach((c, i) => {
      const t = CARDS[c.cardCode]?.holdFacts?.runnerTurnStart;
      if (!t) return;
      if (t.counters.kind === 'virus') virus[i] += t.counters.n;
      if (t.counters.kind === 'power') power[i] += t.counters.n;
      if (t.derezHostAt !== undefined && c.hostedOnId && virus[i] >= t.derezHostAt) derezzed.add(c.hostedOnId);
    });
  }
  return { rig, index, virus, power, derezzed, runnerTurn, fresh: runnerTurn && fresh };
}

/** The server's ice as the walk meets it, innermost first; inS and bypassed are set per rez set. */
export function walkIce(state: GameState, start: WalkStart, ice: CardInstance[]): WalkIce[] {
  // The subroutines broken on the encounter under way are this run's (review R2): a 'runnerTurn' question is about the
  // Runner's next turn, where every encounter is new (6.9.3)
  const encounter = start.runnerTurn ? undefined : state.activeRun?.encounter;
  // The Corp's identity: what ice of some subtypes gains when it is rezzed during a run (Thunderbolt Armaments)
  const anyIce = CARDS[state.corp.identity?.cardCode]?.holdFacts?.rezDuringRun?.anyIce;
  return ice.map(c => {
    const rezzed = c.isRezzed && !start.derezzed.has(c.instanceId);
    const choices = rezzed ? undefined : CARDS[c.cardCode]?.holdFacts?.rezChoosesSubtypes;
    // An ice whose subtypes the Corp chooses at its rez is met without an earlier choice (the derez clears it)
    const up = choices ? { ...c, isRezzed: true, chosenSubtypes: undefined } : c.isRezzed ? c : { ...c, isRezzed: true };
    const view = withIce(state, up);
    const hostedHere = (f: (x: CardInstance) => boolean) => start.rig.flatMap((r, i) => (r.hostedOnId === c.instanceId && f(r) ? [i] : []));
    const bypassers = hostedHere(r => !!CARDS[r.cardCode]?.holdFacts?.hostBypass).map(i => {
      const b = CARDS[start.rig[i].cardCode].holdFacts!.hostBypass!;
      return { idx: i, per: b.creditsPerSubroutine, unless: b.unlessSubtype };
    });
    const subs = plannedSubroutines(view, up).map(sub => subroutineFacts(sub.label));
    const bioroid = isBioroid(c);
    return {
      card: up,
      id: c.instanceId,
      rezzed,
      rezCost: rezCostOf(state, c),
      inS: false,
      bypassed: false,
      subs,
      types: iceSubtypes(up, state),
      botulus: hostedHere(r => !!CARDS[r.cardCode]?.holdFacts?.breaksHostSubroutine),
      bypassers,
      selfCredits: iceScript(c)?.runnerBreakCost,
      bioroid,
      breakClicks: bioroid ? Array.from({ length: subs.length + 2 }, (_, y) => bioroidBreakClicks(up, y)) : [],
      anyBreaker: canBreakSubroutinesWith(c, null),
      rezFacts: CARDS[c.cardCode]?.holdFacts?.rezDuringRun,
      encounterFacts: CARDS[c.cardCode]?.holdFacts?.encounter,
      granters: hostedHere(r => !!getCardScript(r.cardCode)?.grantsIceSubtypes?.length),
      broken: encounter?.iceId === c.instanceId ? [...encounter.broken] : undefined,
      // AP and destroyer are printed subtypes only (iceSubtypes reads barrier, code gate and sentry, the ones a card grants)
      rezGains: anyIce && (cardDef(c).keywords ?? '').toLowerCase().split(/\s*-\s*/).some(k => anyIce.subtypes.includes(k)) ? subroutineFacts(anyIce.gains) : undefined,
      liability: !!CARDS[c.cardCode]?.holdFacts?.rezBadPublicityOrTag,
      choices,
    };
  });
}

/**
 * A server's ice as met (walkIce), once per board, server and kind of start: serverHold's question and the run sequence's
 * ask it of the same boards (the 14:39Z ruling: gathered once; a turn's start or the rest of a turn (startKind), and the
 * key names the start's kind so a 'thisRun' start is never served the turn's ice). On valueModel's memo, so it is
 * dropped when the board is changed in place.
 */
function turnIce(state: GameState, start: WalkStart, server: string): WalkIce[] {
  return memo(state, `turnIce:${startKind(start)}:${server}`, () => walkIce(state, start, state.corp.servers[server]?.ice ?? []));
}


/** A start's kind in a memo key: 0 the run under way, 1 the next turn, 2 the rest of this turn. */
const startKind = (start: WalkStart): number => (!start.runnerTurn ? 0 : start.fresh ? 1 : 2);

/** The board with the hosted subtype-giving cards at rig indexes `off` taken off (for the ice's subtypes and plans). */
function without(state: GameState, start: WalkStart, off: number[]): GameState {
  if (!off.length) return state;
  const ids = new Set(off.map(i => start.rig[i].instanceId));
  return { ...state, runner: { ...state.runner, rig: { ...state.runner.rig, programs: state.runner.rig.programs.filter(c => !ids.has(c.instanceId)) } } };
}

/** The walk's board for `targets` (WalkBoard): everything the search reads, from the board. */
export function walkBoard(state: GameState, start: WalkStart, targets: WalkTarget[]): WalkBoard {
  // Each ice's break plans, by the number of subroutines, worked out once per board (time condition: not once per rez
  // set), on valueModel's memo (review R3: dropped when the board is changed in place, keyed by the pricing context);
  // by the walk's kind too, as its start reads the rig
  const cache = memo(state, `walkPlans:${startKind(start)}`, () => new Map<string, WalkPlan[]>());
  const plans: Record<string, WalkPlan[]> = {};
  const types: Record<string, string[]> = {};
  const ices = new Map(targets.flatMap(t => t.ice.map(i => [i.id, i] as const)));
  for (const ice of ices.values()) {
    const n = ice.subs.length + (ice.rezGains ? 1 : 0);
    for (let mask = 0; mask < 1 << ice.granters.length; mask++) {
      const off = ice.granters.filter((_, k) => mask & (1 << k));
      const board = without(state, start, off);
      for (const k of ['', ...(ice.choices ?? []).map((_, i) => String(i))]) {
        const card = k === '' ? ice.card : { ...ice.card, chosenSubtypes: ice.choices![Number(k)] };
        if (off.length || k !== '') types[`${ice.id}|${off}|${k}`] = iceSubtypes(card, board);
        for (let z = 1; z <= n; z++) {
          const key = `${ice.id}|${z}|${off}|${k}`;
          let list = cache.get(key);
          if (!list) cache.set(key, (list = planFor(board, start, card, z)));
          plans[key] = list;
        }
      }
    }
  }
  const borrows = [...ices.values()].some(i => i.subs.some(f => f.does.some(e => e.kind === 'borrow')));
  return {
    badPublicity: state.corp.badPublicity,
    threat: threatLevel(state),
    hq: state.corp.hq.length,
    tags: state.runner.tags,
    grip: state.runner.grip.length,
    rig: start.rig.map(c => {
      const keywords = cardDef(c).keywords ?? '';
      return { trojan: /\btrojan\b/i.test(keywords), purgeTrash: !!CARDS[c.cardCode]?.holdFacts?.trashedOnPurge, counted: !!CARDS[c.cardCode]?.holdFacts?.breaksHostSubroutine || /icebreaker/i.test(keywords) };
    }),
    lenders: borrows ? lenders(state, targets) : [],
    plans,
    types,
    bypass: !!plan().bypass,
    firstDraw: [...start.rig, state.runner.identity].reduce((n, c) => Math.max(n, (c && getCardScript(c.cardCode)?.modifiers?.firstBasicDraw) || 1), 1),
  };
}

/** breakPlans for `z` of the ice's subroutines, as the walk spends them (rig indexes). */
function planFor(board: GameState, start: WalkStart, card: CardInstance, z: number): WalkPlan[] {
  return breakPlans(withIce(board, card), card, z).flatMap(({ plan: p, spends }) => {
    const breaker = start.index.get(p.breaker.instanceId);
    if (breaker === undefined) return [];
    const c = spends.counters;
    const idx = c ? start.index.get(c.cardId) : undefined;
    return [{
      breaker,
      credits: p.credits,
      stealth: spends.stealthCredits ?? 0,
      counter: c && idx !== undefined ? { idx, kind: c.kind, n: c.n } : undefined,
      grip: spends.gripCards ?? 0,
      mayfly: !!spends.trashesBreaker,
      spike: !!spends.oncePerRun,
    }];
  });
}

/** The walk (exported with its parts for tests/holdWalkReference.test.ts, the brute-force reference; brief section 6). */
export class Walk {
  /** Per target and ice position: the rez-set and bypass flags of that ice and every ice inward of it, the part of the
   * set an approach there reads (a memo shared across the rez sets of one question keys on it). */
  private readonly inner: string[][];
  /** Per target: the flags of the targets after it (a later run reads all of its ice). */
  private readonly later: string[];
  /** The rig cards whose counters the walk reads (breakers, Botulus): the others' counters stay out of the memo key. */
  private readonly counted: number[];
  /** By run: whether its approaches read the Runner's clicks (key them by clicks). The last run's breach ends the walk, so
   * its clicks are read only by a bioroid's click breaks and a toll paid in clicks; on any other run, by the runs after. */
  private readonly clicksRead: boolean[];
  /** The ice a borrowed subroutine may come from, with its subroutines' facts (borrow). */
  private readonly lenders: Lender[];
  /** A draw can matter (some damage, a grip condition or a grip-spending plan on the way). */
  private readonly drawUseful: boolean;
  /** Removing a tag can matter (some condition or effect reads the Runner's tags). */
  private readonly tagUseful: boolean;

  constructor(
    /** What it reads of the board, gathered (walkBoard): the search has no `state` in scope. */
    private readonly board: WalkBoard,
    private readonly targets: SearchTarget[],
    /** The memo, shared by the walks of one question over its rez sets (keys carry the flags they read). */
    private readonly memo = new Map<string, number>(),
    /**
     * A run that ends is followed by the rest of the turn (the failed run, above): the turn goes on from the state the run
     * left, and the same target is run again while clicks remain. Off for the gate's single runs and for 'thisRun' (a new
     * run is not this run). The two kinds never share a memo (WalkMemos).
     */
    private readonly retries = false,
  ) {
    // Keys name the server and the runs still to make, not the run's index: the last run of a sequence and a single run
    // on the same server share their nodes (sequenceEntries, turnReach)
    const flags = (i: SearchIce) => `${i.inS ? 1 : 0}${i.bypassed ? 1 : 0}`;
    // An approach reads the flags of the ice inward of it; with retries, a run that ends there is run again from the
    // outermost ice, so it reads them all
    this.inner = targets.map(t => t.ice.map((_, pos) => `${t.server}:${t.ice.slice(0, retries ? t.ice.length : pos + 1).map(flags).join('')}`));
    this.later = targets.map((_, j) => targets.slice(j + 1).map(t => `${t.server}:${t.ice.map(flags).join('')}`).join('/'));
    // With retries every run's clicks are read (a run that ends leaves the rest of them for the next)
    this.clicksRead = targets.map((t, j) => retries || j < targets.length - 1 || t.ice.some(i => i.bioroid || i.encounterFacts?.unless?.clicks !== undefined));
    this.counted = board.rig.flatMap((r, i) => (r.counted ? [i] : []));
    const facts = targets.flatMap(t => t.ice.flatMap(i => (i.rezGains ? [...i.subs, i.rezGains] : i.subs)));
    const effects = facts.flatMap(f => f.does);
    const borrows = effects.filter(e => e.kind === 'borrow').length;
    // What a borrow can resolve: the subroutines of every ice it may lend from (borrow, below), gathered
    this.lenders = borrows ? board.lenders : [];
    const lent = this.lenders.flatMap(l => l.facts);
    const all = [...facts, ...lent];
    const allEffects = all.flatMap(f => f.does);
    const encounters = targets.flatMap(t => t.ice.flatMap(i => (i.encounterFacts ? [i.encounterFacts] : [])));
    // A draw helps only when the grip can run short (10.4.4): the most the targets can take from it on one pass (damage,
    // net damage paid instead, X counted at the most tags the walk can carry; each borrow at the most one lent subroutine
    // takes) is more than it holds, or any at all when a run may be made again; a grip condition or a plan that spends
    // grip cards (Audrey v2: a plan with `grip`) always counts
    const most = (list: number[]) => list.reduce((a, b) => Math.max(a, b), 0);
    const sum = (list: number[]) => list.reduce((a, b) => a + b, 0);
    const tagsOf = (f: SubFacts) => sum(f.does.map(e => (e.kind === 'tags' && typeof e.n === 'number' ? e.n : 0)));
    const tagGains = targets.flatMap(t => t.ice.map(i => (i.rezFacts?.tags ?? 0) + (i.encounterFacts?.toll?.tags ?? 0) + (i.encounterFacts?.unless?.tags ?? 0)));
    const tagsMost = board.tags + sum(tagGains) + sum(facts.map(tagsOf)) + borrows * most(lent.map(tagsOf));
    const gripOf = (f: SubFacts) => sum(f.does.map(e => (e.kind === 'damage' ? (e.n === 'runnerTags' ? tagsMost : e.n) : 0))) + (f.unless?.netDamage ?? 0);
    const gripMost = sum(facts.map(gripOf)) + sum(encounters.map(e => e.unless?.netDamage ?? 0)) + borrows * most(lent.map(gripOf));
    const doubling = allEffects.some(e => e.kind === 'tags' && e.n === 'runnerTags');
    // With retries a run may be made again, so any damage can add up past the grip
    this.drawUseful = doubling || allEffects.some(e => e.kind === 'endRun' && e.if?.kind === 'hqMoreThanGrip') || Object.values(board.plans).some(list => list.some(p => p.grip > 0)) || gripMost > board.grip || (retries && gripMost > 0);
    this.tagUseful = all.some(f => f.when?.kind === 'runnerTagsAtLeast') || allEffects.some(e => (e.kind === 'endRun' && e.if?.kind === 'runnerTagsAtLeast') || ((e.kind === 'damage' || e.kind === 'tags') && e.n === 'runnerTags') || (e.kind === 'corpGainsCredits' && e.n === 'perRunnerTag'));
  }

  /** The walk state in a memo key (run j: the clicks only where they are read, the stack where a run may follow). */
  private wsKey(ws: WalkState, j: number): string {
    return `${this.clicksRead[j] ? ws.clicks : '-'}|${ws.tags}|${ws.grip}|${this.retries || j < this.targets.length - 1 ? ws.stack : '-'}|${ws.corp}|${ws.fund}|${ws.hosted}|${ws.stealth}|${this.counters(ws)}|${ws.gone}|${ws.up}|${ws.spike ? 1 : 0}|${ws.mayfly}|${ws.drew ? 1 : 0}|${ws.chose}|${ws.trashed}|${ws.bp}${this.retries ? (ws.moved ? '|1' : '|0') : ''}`;
  }

  /** The counters the walk reads, for a memo key. */
  private counters(ws: WalkState): string {
    let s = '';
    for (const i of this.counted) s += `${ws.virus[i]},${ws.power[i]};`;
    return s;
  }

  /** The least pool that gets the Runner through every target in order, its turn's clicks in `ws` (runnerTurn). */
  turn(ws: WalkState): number {
    return this.beforeRun(ws, 0);
  }

  /** The least pool from the approach of the ice at `pos` of the first target (thisRun: the run under way). */
  fromIce(ws: WalkState, pos: number): number {
    return this.approach(ws, 0, pos);
  }

  /**
   * Before run j: the Runner may draw (5.2.7c) or remove a tag (5.2.7g: a click and 2 credits) with a click it keeps
   * clear of the runs still to make, then runs (5.2.7f). Earning comes first (runnerEarnings at the turn's start): a
   * credit in the pool earlier is never worse.
   */
  private beforeRun(ws: WalkState, j: number): number {
    const runs = this.targets.length - j;
    if (ws.clicks < runs) return FAIL;
    const key = `b|${this.inner[j][this.targets[j].ice.length - 1] ?? this.targets[j].server}|${this.later[j]}|${ws.clicks}|${ws.tags}|${ws.grip}|${ws.stack}|${ws.corp}|${ws.hosted}|${ws.stealth}|${this.counters(ws)}|${ws.gone}|${ws.up}|${ws.drew ? 1 : 0}|${ws.chose}|${ws.trashed}|${ws.bp}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    // 6.9.1b, 10.6.3a: the bad publicity fund is filled as each run begins, with what the Corp took on earlier runs
    const fund = this.board.badPublicity + ws.bp;
    let best = this.approach({ ...ws, clicks: ws.clicks - 1, spike: false, fund, moved: false }, j, this.targets[j].ice.length - 1);
    if (ws.clicks > runs) {
      if (this.drawUseful && ws.stack > 0) {
        // 5.2.7c; the turn's first draw may give more (WalkBoard.firstDraw), at most the stack
        const n = Math.min(ws.stack, ws.drew ? 1 : this.board.firstDraw);
        best = Math.min(best, this.beforeRun({ ...ws, clicks: ws.clicks - 1, grip: ws.grip + n, stack: ws.stack - n, drew: true }, j));
      }
      if (this.tagUseful && ws.tags > 0) best = Math.min(best, this.beforeRun({ ...ws, clicks: ws.clicks - 1, tags: ws.tags - 1 }, j) + 2);
    }
    this.memo.set(key, best);
    return best;
  }

  /** The breach of run j (6.9.5): the turn goes on to the next target, Mayfly trashed as the run ends. */
  private breach(ws: WalkState, j: number): number {
    if (j + 1 >= this.targets.length) return 0;
    // 6.9.6b, 10.6.3b: what is left in the bad publicity fund goes back to the bank
    return this.beforeRun({ ...ws, fund: 0, gone: [...ws.gone, ...ws.mayfly].sort((a, b) => a - b), mayfly: [] }, j + 1);
  }

  /**
   * Run j ended before its breach (a subroutine or a toll ended it, 6.1.4): with retries the turn goes on from the state
   * it left, which the walk carries (the ice it rezzed stay rezzed, the Corp's credits, the counters, tags and grip, the
   * click spent), and run j is made again while clicks remain; what lasts "for this run" ends with it (the fund goes back,
   * 10.6.3b; Mayfly is trashed; Pressure Spike's use and a rez's gained subroutine, Thunderbolt's, are the run's only).
   * Without retries an ended run fails. A flatline (10.4.4) is not an ended run: the game is over.
   * The cut (109ae85, kept by the design answer of 16:29Z): a run is made again only if it `moved`, that is changed
   * something a later run reads in the Runner's favour. Everything of the brief's 2.2 a failed run leaves for the Runner
   * sets it, and a fact added to "what stays" must be added here: a rez (with it the Corp's credits spent, a lasting
   * choice such as Lycian's, a rez-time fact used up such as Ping's tag; set at any rez, one the Corp pays 0 for too),
   * a Corp gain of credits, an ice that trashed itself. All else a run changes (a click, tags, damage, credits, counters
   * or cards spent) leaves the Runner no better off than at its start, where every way on was open already, so a retry
   * finds nothing new. The brute-force reference (tests/holdWalkReference.test.ts) keeps no cut.
   */
  private ended(ws: WalkState, j: number): number {
    if (!this.retries || !ws.moved) return FAIL;
    return this.beforeRun({ ...ws, fund: 0, gone: [...ws.gone, ...ws.mayfly].sort((a, b) => a - b), mayfly: [] }, j);
  }

  private approach(ws: WalkState, j: number, pos: number): number {
    if (pos < 0) return this.breach(ws, j);
    const at = `${pos}|${this.inner[j][pos]}|${this.later[j]}`;
    const key = `${at}|${this.wsKey(ws, j)}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    const ice = this.targets[j].ice[pos];
    const next = (w: WalkState) => this.approach(w, j, pos - 1);
    let v: number;
    // An ice that trashed itself on an earlier run of the turn is not there (passed as if it were not installed)
    if (ws.trashed.includes(ice.id)) v = next(ws);
    else if (!ice.rezzed && !ws.up.includes(ice.id)) {
      // 6.9.2c: unrezzed ice the Corp does not rez is passed; 6.4.3: ice of S is rezzed as it is approached
      const paid = ws.corp - ice.rezCost;
      v = ice.inS && paid >= 0 ? this.liability({ ...ws, corp: paid, up: [...ws.up, ice.id].sort(), moved: true }, ice, w => this.rezzed(w, ice, next, { key: at, j })) : next(ws);
    } else v = ice.bypassed ? next(ws) : this.encounter(ws, ice, next, { key: at, j });
    this.memo.set(key, v);
    return v;
  }

  /**
   * A liability rez's additional cost (Valentão, Piranhas: "take 1 bad publicity or remove 1 tag"; 1.14.3a), the
   * Corp's choice worse for the Runner (ruling 6): the bad publicity fills the fund from the next run on (10.6.3c), the
   * tag is gone at once. Paid before the rez's own effects.
   */
  private liability(ws: WalkState, ice: SearchIce, then: (w: WalkState) => number): number {
    if (!ice.liability) return then(ws);
    const bp = then({ ...ws, bp: ws.bp + 1 });
    return ws.tags > 0 ? Math.max(bp, then({ ...ws, tags: ws.tags - 1 })) : bp;
  }

  /** The ice was rezzed during this run against its server: its rez-time facts (Flyswatter: purge virus counters). */
  private rezzed(ws: WalkState, ice: SearchIce, next: (w: WalkState) => number, at: Step): number {
    if (ice.choices && this.choiceOf(ice, ws) === '') {
      // Lycian: the Corp chooses the ice's subtypes as it rezzes it, the choice worst for the Runner (ruling 6)
      let worst = -Infinity;
      ice.choices.forEach((_, k) => (worst = Math.max(worst, this.rezzed({ ...ws, chose: [...ws.chose, `${ice.id}:${k}`].sort() }, ice, next, at))));
      return worst;
    }
    let w = ws;
    if (ice.rezFacts?.purgeVirus) {
      // Purging removes every virus counter (10.3.5); Physarum Entangler is trashed by it (its text)
      const purged = this.board.rig.flatMap((r, i) => (r.purgeTrash ? [i] : []));
      w = { ...w, virus: w.virus.map(() => 0), gone: [...new Set([...w.gone, ...purged])].sort((a, b) => a - b) };
    }
    if (ice.rezFacts?.tags) w = { ...w, tags: w.tags + ice.rezFacts.tags };
    // Thunderbolt Armaments: the ice gains its subroutine after its others for the rest of the run (9.8.3e)
    const met = ice.rezGains ? { ...ice, subs: [...ice.subs, ice.rezGains] } : ice;
    const go = (x: WalkState) => (ice.bypassed ? next(x) : this.encounter(x, met, next, at));
    if (ice.rezFacts?.corpMayTrashInstalled === 'trojan') {
      // Bumi 1.0: the Corp may trash 1 installed trojan, the choice worst for the Runner (ruling 6)
      let worst = go(w);
      this.board.rig.forEach((r, i) => {
        if (!w.gone.includes(i) && r.trojan) worst = Math.max(worst, go({ ...w, gone: [...w.gone, i].sort((a, b) => a - b) }));
      });
      return worst;
    }
    return go(w);
  }

  /**
   * An encounter: the Runner's own bypass first (Physarum, its trigger as the active player's), then what the ice does as
   * the encounter begins (6.9.3a), then its choice of the subroutines to break and how; the rest resolve in order.
   */
  private encounter(ws: WalkState, ice: SearchIce, next: (w: WalkState) => number, at: Step): number {
    const subs = ice.subs;
    const types = this.typesOf(ice, ws);
    let best = FAIL;
    if (this.board.bypass) {
      for (const b of ice.bypassers) if (!ws.gone.includes(b.idx) && !types.includes(b.unless)) best = Math.min(best, this.pay(ws, b.per * subs.length, next));
    }
    return Math.min(best, this.tolls(ws, ice, w => this.breaks(w, ice, types, next, at), at));
  }

  /** The ice's subtypes now: a Corp trash of a hosted card that gives subtypes (Chromatophores) takes them away. */
  private typesOf(ice: SearchIce, ws: WalkState): string[] {
    const off = ice.granters.filter(i => ws.gone.includes(i));
    const k = this.choiceOf(ice, ws);
    return off.length || k !== '' ? this.board.types[`${ice.id}|${off}|${k}`] : ice.types;
  }

  /** The Corp's choice of the ice's subtypes at its rez during the walk (its index in `choices`), or '' (none made). */
  private choiceOf(ice: SearchIce, ws: WalkState): string {
    if (!ice.choices) return '';
    const c = ws.chose.find(x => x.startsWith(`${ice.id}:`));
    return c ? c.slice(ice.id.length + 1) : '';
  }

  /**
   * What the ice does as the encounter begins (6.9.3a): a toll unless the Runner pays one of the alternatives, its
   * choice (Funhouse: end the run unless it takes 1 tag; Seraph: lose 3 unless it suffers 2 net damage or takes 1 tag;
   * Jaguarundi at threat 4: a tag unless it spends a click).
   */
  private tolls(ws: WalkState, ice: SearchIce, then: (w: WalkState) => number, at: Step): number {
    const e = ice.encounterFacts;
    if (!e || ice.broken || (e.threatAtLeast !== undefined && this.board.threat < e.threatAtLeast)) return then(ws);
    // Paywall: the Runner loses credits as the encounter begins (6.9.3a), from its pool (10.6.2: not the fund)
    if (e.loses) return lose(this.toll(ws, e, then, at), e.loses);
    return this.toll(ws, e, then, at);
  }

  /** The encounter toll and the alternatives the Runner may pay instead, its choice. */
  private toll(ws: WalkState, e: NonNullable<SearchIce['encounterFacts']>, then: (w: WalkState) => number, at: Step): number {
    if (!e.toll) return then(ws);
    const t = e.toll;
    let best = t.endRun ? this.ended(ws, at.j) : t.loses ? lose(then(ws), t.loses) : then({ ...ws, tags: ws.tags + (t.tags ?? 0) });
    const u = e.unless ?? {};
    if (u.tags) best = Math.min(best, then({ ...ws, tags: ws.tags + u.tags }));
    if (u.netDamage !== undefined && u.netDamage <= ws.grip) best = Math.min(best, then({ ...ws, grip: ws.grip - u.netDamage }));
    if (u.clicks !== undefined && u.clicks <= ws.clicks) best = Math.min(best, then({ ...ws, clicks: ws.clicks - u.clicks }));
    return best;
  }

  /** The Runner's choice of the subroutines to break and how (a plan, Botulus's counters, the ice's own ability). */
  private breaks(ws: WalkState, ice: SearchIce, types: string[], next: (w: WalkState) => number, at: Step): number {
    const subs = ice.subs;
    let best = FAIL;
    // An inert subroutine resolves to nothing (breaking it never helps): left out of the choice and of the resolution
    const open = subs.map((_, i) => i).filter(i => !ice.broken?.[i] && !inert(subs[i]));
    for (let set = 0; set < 1 << open.length; set++) {
      const unbroken = open.filter((_, k) => !(set & (1 << k)));
      // A subroutine left unbroken that always ends the run ends it there: without retries the way fails; with them it is
      // a way to end the run, and breaking a subroutine after it buys nothing (it never resolves)
      const first = unbroken.find(i => alwaysEnds(subs[i]));
      if (first !== undefined && (!this.retries || open.some((i, k) => i > first && set & (1 << k)))) continue;
      const b = open.length - unbroken.length;
      const resolve = (w: WalkState) => this.resolve(w, ice, types, unbroken, 0, next, at);
      if (b === 0) {
        best = Math.min(best, resolve(ws));
        continue;
      }
      const hosted = ice.anyBreaker ? ice.botulus.filter(i => !ws.gone.includes(i)) : [];
      const counters = hosted.reduce((n, i) => n + ws.virus[i], 0);
      for (let x = 0; x <= Math.min(b, counters); x++) {
        const w1 = x ? this.spendBotulus(ws, hosted, x) : ws;
        for (let y = 0; y <= b - x; y++) {
          if (y > 0 && !ice.bioroid && ice.selfCredits === undefined) break;
          const clicks = ice.bioroid && y > 0 ? ice.breakClicks[y] : 0;
          if (clicks > w1.clicks) break;
          const w2 = clicks ? { ...w1, clicks: w1.clicks - clicks } : w1;
          const self = (w: WalkState, then: (w: WalkState) => number) => (ice.selfCredits !== undefined && y > 0 ? this.pay(w, y * ice.selfCredits, then) : then(w));
          const z = b - x - y;
          if (z === 0) {
            best = Math.min(best, self(w2, resolve));
            continue;
          }
          for (const p of this.planList(ice, z, w2)) if (this.usable(w2, p)) best = Math.min(best, self(w2, w => this.payPlan(w, p, resolve)));
        }
      }
    }
    return best;
  }

  private spendBotulus(ws: WalkState, hosted: number[], x: number): WalkState {
    const virus = [...ws.virus];
    let left = x;
    for (const i of hosted) {
      const n = Math.min(left, virus[i]);
      virus[i] -= n;
      left -= n;
    }
    return { ...ws, virus };
  }

  private planList(ice: SearchIce, z: number, ws: WalkState): WalkPlan[] {
    return this.board.plans[`${ice.id}|${z}|${ice.granters.filter(i => ws.gone.includes(i))}|${this.choiceOf(ice, ws)}`] ?? [];
  }

  private usable(ws: WalkState, p: WalkPlan): boolean {
    if (ws.gone.includes(p.breaker) || (p.spike && ws.spike) || p.stealth > ws.stealth || p.grip > ws.grip) return false;
    return !p.counter || (p.counter.kind === 'virus' ? ws.virus : ws.power)[p.counter.idx] >= p.counter.n;
  }

  private payPlan(ws: WalkState, p: WalkPlan, then: (w: WalkState) => number): number {
    const w: WalkState = { ...ws, stealth: ws.stealth - p.stealth, spike: ws.spike || p.spike, grip: ws.grip - p.grip };
    if (p.counter) {
      const list = [...(p.counter.kind === 'virus' ? w.virus : w.power)];
      list[p.counter.idx] -= p.counter.n;
      if (p.counter.kind === 'virus') w.virus = list;
      else w.power = list;
    }
    if (p.mayfly && !w.mayfly.includes(p.breaker)) w.mayfly = [...w.mayfly, p.breaker].sort((a, b) => a - b);
    return this.pay(w, p.credits - p.stealth, then);
  }

  /**
   * Pays `n` credits during the run in the engine's order (spendCredits), which gives the Runner no choice of source: the
   * fund (bad publicity, then the run's bonus credits; 10.6.2: not part of the pool), then the credits on cards that pay
   * during runs (`hosted`, then the stealth cards': Methuselah, Touchstone), then the pool. The pool part is added to what
   * the rest needs. Rule 1.10.3c lets the Runner divide a payment among the allowed sources; the engine does not yet
   * (found-list row 49), and the walk follows the engine: when it gives the choice, a kept stealth credit can beat a pool
   * credit (a later stealth part, a later loss) and pay must try the splits (registry, the hold row's debt).
   */
  private pay(ws: WalkState, n: number, then: (w: WalkState) => number): number {
    const fund = Math.min(n, ws.fund);
    const hosted = Math.min(n - fund, ws.hosted);
    const stealth = Math.min(n - fund - hosted, ws.stealth);
    const w = fund || hosted || stealth ? { ...ws, fund: ws.fund - fund, hosted: ws.hosted - hosted, stealth: ws.stealth - stealth } : ws;
    return then(w) + n - fund - hosted - stealth;
  }

  /** The unbroken subroutines `list` (indexes into ice.subs) resolve one at a time in printed order (9.8.7b). */
  private resolve(ws: WalkState, ice: SearchIce, types: string[], list: number[], k: number, next: (w: WalkState) => number, at: Step): number {
    if (k >= list.length) return next(ws);
    const go = () => this.subroutine(ws, ice.id, types, ice.subs[list[k]], w => this.resolve(w, ice, types, list, k + 1, next, at), at);
    // A borrowing ice (Mycoweb) branches on every subroutine it may lend, each with the rest of its own to resolve: the
    // steps after the first are keyed (`at`: the approach and run; the subroutines as met, those left, the state)
    if (k === 0 || !ice.subs.some(f => f.does.some(e => e.kind === 'borrow'))) return go();
    const key = `s|${at.key}|${ice.subs.length}|${list}|${k}|${this.wsKey(ws, at.j)}`;
    const hit = this.memo.get(key);
    if (hit !== undefined) return hit;
    const v = go();
    this.memo.set(key, v);
    return v;
  }

  /** One subroutine resolves (or the Runner pays its nested cost instead, 1.16.11b). */
  private subroutine(ws: WalkState, card: string, types: string[], f: SubFacts, then: (w: WalkState) => number, at: Step): number {
    if (f.when && !(f.when.kind === 'iceIs' ? types.includes(f.when.subtype) : f.when.kind === 'runnerTagsAtLeast' && ws.tags >= f.when.n)) return then(ws);
    // "X or end the run": the Corp chooses, and the walk takes the end (ruling 6)
    if (f.orEndRun) return this.ended(ws, at.j);
    let best = this.effects(ws, card, f.does, 0, then, at);
    // "unless the Runner pays N" (1.16.11b): paid as it resolves, run-only credits first (10.6.3a: the fund pays any cost
    // during the run)
    if (f.unless?.credits !== undefined) best = Math.min(best, this.pay(ws, f.unless.credits, then));
    // "unless the Runner trashes 1 of their installed cards" (Thunderbolt Armaments): the card it can best spare
    if (f.unless?.trashInstalled) {
      this.board.rig.forEach((_, i) => {
        if (!ws.gone.includes(i)) best = Math.min(best, then({ ...ws, gone: [...ws.gone, i].sort((a, b) => a - b) }));
      });
    }
    if (f.unless?.netDamage !== undefined && f.unless.netDamage <= ws.grip) best = Math.min(best, then({ ...ws, grip: ws.grip - f.unless.netDamage }));
    return best;
  }

  private effects(ws: WalkState, card: string, does: SubEffect[], i: number, then: (w: WalkState) => number, at: Step): number {
    if (i >= does.length) return then(ws);
    const e = does[i];
    const next = (w: WalkState) => this.effects(w, card, does, i + 1, then, at);
    const end = () => this.ended(ws, at.j);
    switch (e.kind) {
      case 'endRun': {
        const c = e.if;
        if (!c) return end();
        // A condition on the pool: the run goes on with a pool over the bound, or ends with one at most it (the ended
        // way only where the rest of the turn needs no more than that)
        if (c.kind === 'runnerCreditsAtMost') {
          const ended = end();
          return Math.min(Math.max(next(ws), c.n + 1), ended <= c.n ? ended : FAIL);
        }
        if (c.kind === 'corpCreditsMoreThanRunner') {
          const ended = end();
          return Math.min(Math.max(next(ws), ws.corp), ended < ws.corp ? ended : FAIL);
        }
        if (c.kind === 'runnerTagsAtLeast') return ws.tags >= c.n ? end() : next(ws);
        if (c.kind === 'threatAtLeast') return this.board.threat >= c.n ? end() : next(ws);
        if (c.kind === 'hqMoreThanGrip') return this.board.hq > ws.grip ? end() : next(ws);
        // Diviner's odd cost: a fact of the grip the walk can't read; left out (the safe side, "does not hold")
        return next(ws);
      }
      case 'runnerLosesClicks':
        return next({ ...ws, clicks: Math.max(0, ws.clicks - e.n) });
      case 'runnerLosesCredits':
        return lose(next(ws), e.n);
      case 'corpGainsCredits':
        return next({ ...ws, corp: ws.corp + (e.n === 'perRunnerTag' ? ws.tags : e.n), moved: true });
      case 'damage': {
        // 10.4.4: more damage than the cards in the grip is a flatline; each point takes a card (10.4.2)
        const n = e.n === 'runnerTags' ? ws.tags : e.n;
        return n > ws.grip ? FAIL : next({ ...ws, grip: ws.grip - n });
      }
      case 'tags':
        return next({ ...ws, tags: ws.tags + (e.n === 'runnerTags' ? ws.tags : e.n) });
      case 'cannotStealOrTrash':
        // Nothing is stolen on this run: as far as the target goes, the run has ended
        return end();
      case 'trashThisIce':
        // "Trash this ice": gone for the rest of the turn (the run goes on inward; a later run does not meet it)
        return next({ ...ws, trashed: [...ws.trashed, card].sort(), moved: true });
      case 'corpMayTrashHqToEndRun':
        return this.board.hq > 0 ? end() : next(ws);
      case 'borrow':
        return this.borrow(ws, card, e.subtype, next, at);
      default:
        // What the walk doesn't carry: trashing or bouncing a Runner card (registry debt: errs toward "does not hold"),
        // the Corp's own side, a jack out the Runner may take
        return next(ws);
    }
  }

  /** Mycoweb: the Corp resolves 1 subroutine of another rezzed ice of the subtype, the one worst for the Runner (ruling 6). */
  private borrow(ws: WalkState, card: string, subtype: string, next: (w: WalkState) => number, at: Step): number {
    let worst = -1;
    for (const l of this.lenders) {
      if (l.id === card || ws.trashed.includes(l.id) || !(l.rezzed || ws.up.includes(l.id)) || !l.types.includes(subtype)) continue;
      for (const f of l.facts) worst = Math.max(worst, this.subroutine(ws, l.id, l.types, f, next, at));
    }
    return worst < 0 ? next(ws) : worst;
  }
}

/** Where an encounter is: its approach's memo key and its run. */
interface Step {
  key: string;
  j: number;
}

/** A borrow's lender: rezzed now, or walked (rezzed when the walk rezzes it), its subroutines but the borrowing ones. */
interface Lender {
  id: string;
  rezzed: boolean;
  types: string[];
  facts: SubFacts[];
}

/** Every ice a borrow may lend from, in board order: the walked ice as met, the rest as the board has it. */
function lenders(state: GameState, targets: WalkTarget[]): Lender[] {
  const walked = new Map(targets.flatMap(t => t.ice.map(x => [x.id, x] as const)));
  return lenderViews(state, walked).flatMap(v => (walked.has(v.id) ? [v.walked!] : v.unwalked ? [v.unwalked] : []));
}

/** Each ice of the board as a lender both ways, in board order: as met when `walked` holds it, and as the board has it (rezzed ice only). */
function lenderViews(state: GameState, walked: Map<string, WalkIce>): { id: string; walked?: Lender; unwalked?: Lender }[] {
  const facts = (c: CardInstance) => iceSubroutines(state, c).filter(sub => !/resolve 1 subroutine on/i.test(sub.label)).map(sub => subroutineFacts(sub.label));
  const out: { id: string; walked?: Lender; unwalked?: Lender }[] = [];
  for (const sv of Object.values(state.corp.servers)) {
    for (const c of sv.ice) {
      const w = walked.get(c.instanceId);
      out.push({
        id: c.instanceId,
        walked: w ? { id: c.instanceId, rezzed: w.rezzed, types: w.types, facts: facts(w.card) } : undefined,
        unwalked: c.isRezzed ? { id: c.instanceId, rezzed: true, types: iceSubtypes(c, state), facts: facts(c) } : undefined,
      });
    }
  }
  return out;
}

/**
 * The run-time credits on the Runner's cards, split with no overlap (audit AI-HOLD-STEALTH-TWICE, found-list row 31):
 * `stealth`, the credits on stealth cards, which pay a plan's stealth part (Corsair) and, during a run, any other cost
 * too; `hosted`, the credits on the other cards that pay during runs, any cost but a stealth part. On the Runner's turn,
 * the rig's (runStealthCredits' stealth cards; Methuselah, Touchstone); during the run under way, the engine's: its run payers
 * (availableCredits less the pool it counts, none with the pool locked, and the fund; Trick Shot's and Aircheck's
 * hosted credits too) and its stealth credits. Read by the turn's first state and the run under way alike.
 */
function runCredits(state: GameState, start: WalkStart): { hosted: number; stealth: number } {
  const run = state.activeRun;
  if (run && !start.runnerTurn) {
    const stealth = stealthCredits(state);
    const pool = run.poolLocked ? 0 : state.runner.credits;
    return { hosted: availableCredits(state, 'runner') - pool - run.bonusCredits - (run.badPublicityCredits ?? 0) - stealth, stealth };
  }
  const sum = (f: (c: CardInstance, stealth: boolean) => boolean) => start.rig.filter(c => f(c, /stealth/i.test(cardDef(c).keywords ?? ''))).reduce((n, c) => n + counters(c, 'credit'), 0);
  return { hosted: sum((c, stealth) => !stealth && !!getCardScript(c.cardCode)?.paysDuringRuns), stealth: sum((_, stealth) => stealth) };
}

/**
 * The walk's first state on the Runner's turn: `clicks` for the turn, the rest from the board at its start. From the rest
 * of a turn (a start not `fresh`), the turn's first basic draw is taken if it was (5.2.7c; WalkBoard.firstDraw).
 */
export function firstState(state: GameState, start: WalkStart, clicks: number, corp: number): WalkState {
  return {
    clicks,
    tags: state.runner.tags,
    grip: state.runner.grip.length,
    stack: state.runner.stack.length,
    drew: start.runnerTurn && !start.fresh && turnFlag(state, TurnFlag.basicDraws) > 0,
    chose: [],
    corp,
    fund: 0,
    ...runCredits(state, start),
    virus: start.virus,
    power: start.power,
    gone: [],
    up: [],
    spike: false,
    mayfly: [],
    bp: 0,
    trashed: [],
    moved: false,
  };
}

/** What one turn's search reads besides its targets: the gathered board, the clicks and what they earn, the first state. */
interface TurnInput {
  board: WalkBoard;
  /** runnerEarnings: what the Runner earns with k clicks. */
  earn: number[];
  maxClicks: number;
  /** The first state, its clicks set per split. */
  first: WalkState;
}

/** The turn's input from the board (gathering: the only part of a question that reads `state`). */
function turnInput(state: GameState, start: WalkStart, targets: WalkTarget[], corp: number, from: TurnFrom = nextTurn(state)): TurnInput {
  return { board: walkBoard(state, start, targets), earn: runnerEarnings(state, from), maxClicks: from.clicks, first: firstState(state, start, from.clicks, corp) };
}

/**
 * The least the Runner must bring for one turn through `targets`, in the budget's units (brief 5.5, over the whole turn:
 * a run that ends may be followed by another): over every split of its clicks, the pool the walk needs plus what the
 * clicks it doesn't earn with would have earned (runnerEarnings).
 */
function turnNeed(input: TurnInput, targets: SearchTarget[], memo?: Map<string, number>, retries = false): number {
  return walkNeed(input, new Walk(input.board, targets, memo, retries), targets.length);
}

/**
 * The memos of one question's walks, one per kind (the design answer of 16:29Z, (d)): the single-run walk and the retry
 * walk never share a key, as a single run's value with FAIL at a run's end is not the turn's.
 */
interface WalkMemos {
  one: Map<string, number>;
  turn: Map<string, number>;
}
const walkMemos = (): WalkMemos => ({ one: new Map(), turn: new Map() });

/**
 * The gate (brief rev 2, 3 (a)): whether one Runner turn gets through `targets` within `budget` (`price` added to each
 * walk's need). A single run per target first: if it gets through, so does the turn (a single run is one of its lines),
 * and no retry is asked. Only where it falls short is the retry walk asked, exact (no bound, no cut but the `moved` one).
 */
function passes(input: TurnInput, targets: SearchTarget[], price: number, budget: number, memos: WalkMemos): boolean {
  return turnNeed(input, targets, memos.one) + price <= budget || turnNeed(input, targets, memos.turn, true) + price <= budget;
}

/** turnNeed with its walk made (reachOrders shares a walk's memo with the walks that read the same). */
function walkNeed(input: TurnInput, walk: Walk, runs: number): number {
  const { earn, first } = input;
  const c = Math.max(0, input.maxClicks);
  let need = FAIL;
  for (let e = 0; e + runs <= c; e++) need = Math.min(need, walk.turn({ ...first, clicks: c - e }) + earn[c - 1] - earn[e]);
  return need;
}

/** The Corp's credits through the walk: the rez budget asked, or its credits and every rez it could make (as the oracle). */
export function corpStart(state: GameState, ice: WalkIce[], corpCredits: number): number {
  return Number.isFinite(corpCredits) ? corpCredits : state.corp.credits + ice.filter(c => !c.rezzed).reduce((n, c) => n + c.rezCost, 0);
}

/** The board runBypasses reads for a rez set: the ice rezzed at the walk's start and the set's. */
function bypassBoard(state: GameState, serverId: string, ice: WalkIce[], set: Set<string>): GameState {
  const server = state.corp.servers[serverId];
  return withServerIce(state, serverId, server.ice.map((c, i) => ({ ...c, isRezzed: ice[i].rezzed || set.has(c.instanceId) })));
}

/** A run of the walk's turn on `server` with `set` to rez: its ice as met, and what its bypasses cost (runBypasses; 6.5.8a). */
export function runTarget(state: GameState, base: WalkIce[], server: string, set: Set<string>, clicks = state.runner.maxClicks): { target: WalkTarget; price: number } {
  const all = state.corp.servers[server]?.ice ?? [];
  // The view runBypasses read before (the Runner's clicks but the run's; `clicks`: the turn's, TurnFrom)
  const view: GameState = { ...state, runner: { ...state.runner, clicks: Math.max(0, clicks - 1) } };
  const bypassed = all.length ? runBypasses(bypassBoard(view, server, base, set), server) : undefined;
  const ice = base.map(c => ({ ...c, inS: set.has(c.card.instanceId), bypassed: !!bypassed?.ids.has(c.card.instanceId) }));
  return { target: { server, ice }, price: bypassed?.price ?? 0 };
}

/**
 * One 'runnerTurn' question, gathered (Stage D item 1, the time stop's ruling 4.3): the server's ice as met with no rez
 * set, the board the search reads, and each rez set the Corp can afford (its mask over the ice, its rez cost, the ice its
 * bypasses skip and their price; the empty set always, as `entries` may need it). The search reads this and nothing else,
 * so the question is its own cache key: equal questions are equal answers, whichever board asked.
 */
export interface TurnQuestion extends TurnInput {
  server: string;
  budget: number;
  ice: SearchIce[];
  sets: { mask: number; rez: number; affordable: boolean; bypassed: number; price: number }[];
}

/** A question's answer: the set that holds (its index in `sets`), or the one that asks the most, and its need. */
interface TurnAnswer {
  holds: boolean;
  set: number;
  need: number;
  /** The further runs (sequenceEntries), worked out when first read; the memos are kept for it until then. */
  entries?: number;
  memos?: WalkMemos;
}

/** Answers per decision (ruling 4.3: never across decisions): keyed by the decision's anchor, so they die with it. */
const turnAnswers = new WeakMap<object, Map<string, TurnAnswer>>();
/** Questions asked and searched (the cache's hits are asked less searched), for the time report and its test. */
export const holdCacheStats = { asked: 0, searched: 0 };

/** The question as its key: every value it holds (a non-finite number by name; a Set, Map or function is refused). */
export function questionKey(q: unknown): string {
  return JSON.stringify(q, (_, v) => {
    if (typeof v === 'number' && !Number.isFinite(v)) return `#${v}`;
    if (v instanceof Set || v instanceof Map || typeof v === 'function') throw new Error('hold question: not plain data');
    return v;
  });
}

function turnQuestion(state: GameState, server: string, corpCredits: number, from: TurnFrom): TurnQuestion {
  const all = state.corp.servers[server]?.ice ?? [];
  const start = walkStart(state, true, !from.rest);
  const base = turnIce(state, start, server);
  const n = Math.min(all.length, 10);
  const sets: TurnQuestion['sets'] = [];
  for (let mask = 0; mask < 1 << n; mask++) {
    let rez = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) rez = base[i].rezzed ? Infinity : rez + base[i].rezCost;
    // A set with an ice rezzed already is the set without it (its rez cost is no rez's; with the rez budget asked
    // as unlimited, by holdingRez, it was walked again for nothing)
    const affordable = rez < Infinity && rez <= corpCredits;
    if (!affordable && mask) continue;
    const { target, price } = runTarget(state, base, server, new Set(all.slice(0, n).filter((_, i) => mask & (1 << i)).map(c => c.instanceId)), from.clicks);
    const bypassed = target.ice.reduce((m, c, i) => (c.bypassed ? m | (1 << i) : m), 0);
    sets.push({ mask, rez, affordable, bypassed, price });
  }
  // Cheapest first, ties in mask order (as before): the first that holds is the answer
  sets.sort((a, b) => a.rez - b.rez || a.mask - b.mask);
  return {
    ...turnInput(state, start, [{ server, ice: base }], corpStart(state, base, corpCredits), from),
    server,
    budget: runnerBudget(state, from),
    ice: base.map(searchIce),
    sets,
  };
}

/** The run of a question's rez set: the ice as met, the set's ice rezzed as approached and its bypasses skipped. */
function setTarget(q: TurnQuestion, k: number): SearchTarget {
  const { mask, bypassed } = q.sets[k];
  return { server: q.server, ice: q.ice.map((c, i) => ({ ...c, inS: !!(mask & (1 << i)), bypassed: !!(bypassed & (1 << i)) })) };
}

/** The search of a question (pure: it reads `q` alone). */
function solveTurn(q: TurnQuestion): TurnAnswer {
  holdCacheStats.searched++;
  const memos = walkMemos();
  let most = -Infinity;
  let mostSet = -1;
  for (let k = 0; k < q.sets.length; k++) {
    if (!q.sets[k].affordable) continue;
    const target = [setTarget(q, k)];
    // `need` is the single run's (brief rev 2, 2.5); the set holds when no line over the turn gets in within the budget:
    // the gate, then the retry walk only where a single run falls short
    const need = turnNeed(q, target, memos.one) + q.sets[k].price;
    if (need > q.budget && turnNeed(q, target, memos.turn, true) + q.sets[k].price > q.budget) return { holds: true, set: k, need };
    if (need > most) [most, mostSet] = [need, k];
  }
  return { holds: false, set: mostSet < 0 ? q.sets.findIndex(x => x.mask === 0) : mostSet, need: most === -Infinity ? 0 : most, memos };
}

/**
 * `entries` from the run sequence (brief 5.6): the most runs on the server one turn gets in on, against the set that asks
 * the most, failed runs between them allowed (brief rev 2, 2.5: the turn decides `entries`; each check through the gate).
 */
function sequenceEntries(q: TurnQuestion, a: TurnAnswer): number {
  const target = setTarget(q, a.set);
  const { price } = q.sets[a.set];
  const memos = a.memos ?? walkMemos();
  // One run gets in (the set that asks the most does not hold); each further run is walked with the nodes shared
  let k = q.maxClicks > 0 ? 1 : 0;
  while (k < q.maxClicks && passes(q, Array(k + 1).fill(target), (k + 1) * price, q.budget, memos)) k++;
  return k;
}

/** 'runnerTurn' (and 'restOfTurn', from its start) by the walk: the cheapest affordable rez set that keeps the Runner out, or the one that asks the most. */
function walkRunnerTurn(state: GameState, server: string, corpCredits: number, from: TurnFrom = nextTurn(state)): Hold {
  const q = turnQuestion(state, server, corpCredits, from);
  holdCacheStats.asked++;
  const anchor = pricing().anchor;
  let cache = anchor ? turnAnswers.get(anchor) : undefined;
  if (anchor && !cache) turnAnswers.set(anchor, (cache = new Map()));
  const key = cache ? questionKey(q) : '';
  let a = cache?.get(key);
  if (!a) {
    a = solveTurn(q);
    cache?.set(key, a);
  }
  const { budget } = q;
  const { need } = a;
  const ids = (k: number) => q.ice.slice(0, 10).filter((_, i) => q.sets[k].mask & (1 << i)).map(c => c.id);
  if (a.holds) return { holds: true, rez: ids(a.set), rezCost: q.sets[a.set].rez, need, budget, margin: need - budget, entries: 0 };
  // Worked out when read: two readers of the count's many (the ice move, iceCount) read `entries`, and the further runs
  // are most of a count's work (rez money asks every staked server of every board the planner looks at)
  const answer = a;
  return {
    holds: false,
    rez: null,
    rezCost: Infinity,
    need,
    budget,
    margin: need - budget,
    get entries() {
      if (answer.entries === undefined) {
        answer.entries = sequenceEntries(q, answer);
        answer.memos = undefined;
      }
      return answer.entries;
    },
  };
}

/**
 * The run sequence (brief 5.6): whether one Runner turn reaches the breach of each server in `servers` in that order,
 * the Corp rezzing the ice of `rezSets[i]` on run i as it is approached and nothing else: one split of the turn's clicks,
 * the fund filled at each run, the credits hosted on cards and the counters shared, the board carried from run to run
 * (an ice rezzed on one run is met rezzed on the next). `need` is in runnerBudget's units, as serverHold's. Each run's
 * bypasses are priced again (a known gap: a counter one bypass spends is not taken from the next).
 * A test and script entry point (the brute-force reference, scripts/stage-d): no reader in src; keepFor reads
 * reachQuestion and reachSets, which answer the same.
 */
export function turnReach(state: GameState, servers: string[], rezSets: string[][], corpCredits = state.corp.credits): { reaches: boolean; need: number; budget: number } {
  return counted(() => {
    const budget = runnerBudget(state);
    if (!servers.length) return { reaches: true, need: 0, budget };
    const start = walkStart(state, true);
    const bases = new Map<string, WalkIce[]>();
    const baseOf = (id: string) => bases.get(id) ?? bases.set(id, turnIce(state, start, id)).get(id)!;
    const runs = servers.map((id, i) => runTarget(state, baseOf(id), id, new Set(rezSets[i] ?? [])));
    const corp = corpStart(state, [...bases.values()].flat(), corpCredits);
    const targets = runs.map(r => r.target).map(searchTarget);
    const input = turnInput(state, start, runs.map(r => r.target), corp);
    const price = runs.reduce((n, r) => n + r.price, 0);
    const memos = walkMemos();
    // `need` is the single runs' (as serverHold's); `reaches` is the turn's, through the gate
    const need = turnNeed(input, targets, memos.one) + price;
    return { reaches: need <= budget || passes(input, targets, price, budget, memos), need, budget };
  });
}

/**
 * The run sequence over a list of servers, gathered once (the 14:39Z ruling on keepFor's time): the walk's start, each
 * server's ice as met with nothing more rezzed and its bypasses' price, the earnings, the first state, and the board for
 * all of them (break plans and subtypes are keyed by ice, so a server outside an order is never read), with each ice as a
 * lender both ways (a borrow lends from the walked ice as met and the rest as the board has it, so the lenders depend on
 * which servers an order runs). `reachOrder` answers turnReach(state, order, no rezzes) from it and nothing else.
 */
export interface ReachQuestion extends TurnInput {
  budget: number;
  targets: Record<string, SearchTarget>;
  prices: Record<string, number>;
  /** Whether a server's ice borrows (walkBoard's rule: then the lenders are gathered). */
  borrows: Record<string, boolean>;
  views: { id: string; server: string | null; walked?: Lender; unwalked?: Lender }[];
}

/** The question for `servers` (the Corp's credits as they are; corpStart with a finite budget is that budget), from `from` (TurnFrom; the rest of a turn asks it of afterRun's board). */
export function reachQuestion(state: GameState, servers: string[], from: TurnFrom = nextTurn(state)): ReachQuestion {
  return counted(() => {
    const start = walkStart(state, true, !from.rest);
    const runs = servers.map(id => runTarget(state, turnIce(state, start, id), id, new Set(), from.clicks));
    const targets = runs.map(r => r.target);
    const input = turnInput(state, start, targets, state.corp.credits, from);
    const walked = new Map(targets.flatMap(t => t.ice.map(x => [x.id, x] as const)));
    const serverOf = new Map(targets.flatMap(t => t.ice.map(x => [x.id, t.server] as const)));
    const borrows = Object.fromEntries(targets.map(t => [t.server, t.ice.some(i => i.subs.some(f => f.does.some(e => e.kind === 'borrow')))]));
    // The lenders are read only by a borrow (setInput, walkBoard's rule)
    const views = Object.values(borrows).some(Boolean) ? lenderViews(state, walked) : [];
    // Nothing is rezzed on these runs (6.4.3: only a rez set's ice is rezzed as approached), so the Corp's credits are
    // read only by a subroutine's "more credits than the Runner", and HQ's size only by "more cards in HQ than in the
    // grip" and "trash 1 card from HQ to end the run": where no subroutine of these servers or of a lender says so, they
    // are left out of the question (0), so that boards differing in them alone ask the same
    const facts = [...targets.flatMap(t => t.ice.flatMap(i => (i.rezGains ? [...i.subs, i.rezGains] : i.subs))), ...views.flatMap(v => [...(v.walked?.facts ?? []), ...(v.unwalked?.facts ?? [])])];
    const ifs = facts.flatMap(f => f.does.map(e => (e.kind === 'endRun' ? e.if?.kind : e.kind)));
    const corpRead = ifs.includes('corpCreditsMoreThanRunner');
    const hqRead = ifs.includes('hqMoreThanGrip') || ifs.includes('corpMayTrashHqToEndRun');
    return {
      ...input,
      first: corpRead ? input.first : { ...input.first, corp: 0 },
      board: { ...input.board, lenders: [], hq: hqRead ? input.board.hq : 0 },
      budget: runnerBudget(state, from),
      targets: Object.fromEntries(targets.map(t => [t.server, searchTarget(t)])),
      prices: Object.fromEntries(runs.map(r => [r.target.server, r.price])),
      borrows,
      views: views.map(v => ({ ...v, server: serverOf.get(v.id) ?? null })),
    };
  });
}

/** The board of the orders of a set of servers: the lenders a borrow reads when those servers are walked. */
function setInput(q: ReachQuestion, set: string[]): TurnInput {
  const on = new Set(set);
  const lenders = set.some(id => q.borrows[id]) ? q.views.flatMap(v => (v.server !== null && on.has(v.server) ? [v.walked!] : v.unwalked ? [v.unwalked] : [])) : [];
  return { ...q, board: { ...q.board, lenders } };
}

/** Whether one Runner turn gets through `order`'s servers in that order, through the gate (its memos given or its own). */
const reaches = (q: ReachQuestion, order: string[], input: TurnInput, memos = walkMemos()): boolean =>
  passes(input, order.map(id => q.targets[id]), order.reduce((n, id) => n + q.prices[id], 0), q.budget, memos);

/**
 * turnReach(state, order, no rezzes) from the gathered question, its own memo (pure: it reads `q` alone). A test and
 * script entry point: no reader in src (reachSets is keepFor's).
 */
export function reachOrder(q: ReachQuestion, order: string[]): boolean {
  return !order.length || reaches(q, order, setInput(q, order));
}

/** Every order of `ids`. */
export const orders = (ids: string[]): string[][] => (ids.length <= 1 ? [ids] : ids.flatMap((id, i) => orders([...ids.slice(0, i), ...ids.slice(i + 1)]).map(rest => [id, ...rest])));

/**
 * The answers per decision (as turnAnswers: on the decision's anchor, never across decisions). An order's answer reads
 * the question's common part (the board but its break plans and lenders, the earnings, the clicks, the first state, the
 * budget, the lenders as the board has them) and the part of each server it runs (its ice as met, the price of its
 * bypasses, whether it borrows, its ice as walked lenders, its ice's plans and subtypes): each part is interned, and an
 * answer is keyed by the common part and the parts it runs, so the questions a decision asks (the staked servers of
 * each board it looks at, with or without a line's agenda) share what they have in common. A set's answer (some order
 * reaches it) is keyed by the common part and its parts. The walks' memos are shared by the orders of one question and
 * set (their node keys name servers, which a question fixes; the set fixes what a node reads besides its key).
 */
interface ReachCache {
  ids: Map<string, number>;
  orders: Map<string, boolean>;
  sets: Map<string, boolean>;
  memos: Map<string, WalkMemos>;
}
const reachAnswers = new WeakMap<object, ReachCache>();

/** Whether some order of a set of the question's servers is reached (reachOrder), cached per decision (above). */
export function reachSets(q: ReachQuestion): (set: string[]) => boolean {
  const anchor = pricing().anchor;
  let c = anchor ? reachAnswers.get(anchor) : undefined;
  if (!c) {
    c = { ids: new Map(), orders: new Map(), sets: new Map(), memos: new Map() };
    if (anchor) reachAnswers.set(anchor, c);
  }
  const cache = c;
  const intern = (x: unknown) => {
    const k = questionKey(x);
    let id = cache.ids.get(k);
    if (id === undefined) cache.ids.set(k, (id = cache.ids.size));
    return id;
  };
  const common = intern({
    board: { ...q.board, plans: {}, types: {}, lenders: [] },
    earn: q.earn,
    maxClicks: q.maxClicks,
    first: q.first,
    budget: q.budget,
    unwalked: q.views.map(v => v.unwalked ?? null),
  });
  const part: Record<string, number> = {};
  for (const [id, t] of Object.entries(q.targets)) {
    const own = (k: string) => t.ice.some(i => k.startsWith(`${i.id}|`));
    part[id] = intern({
      target: t,
      price: q.prices[id],
      borrows: q.borrows[id],
      walked: q.views.filter(v => v.server === id).map(v => v.walked),
      plans: Object.entries(q.board.plans).filter(([k]) => own(k)),
      types: Object.entries(q.board.types).filter(([k]) => own(k)),
    });
  }
  const servers = `${common}|${Object.keys(q.targets).map(id => `${id}=${part[id]}`)}`;
  return set => {
    if (!set.length) return true;
    const sk = `${common}|${set.map(id => part[id]).sort((a, b) => a - b)}`;
    let a = cache.sets.get(sk);
    if (a !== undefined) return a;
    // One board and one memo for the set's orders: the lenders and the walk's options read the set, not its order
    const input = setInput(q, set);
    const mk = `${servers}|${[...set].sort()}`;
    let memo = cache.memos.get(mk);
    if (!memo) cache.memos.set(mk, (memo = walkMemos()));
    a = orders(set).some(order => {
      const k = `${common}|${order.map(id => part[id])}`;
      let r = cache.orders.get(k);
      if (r === undefined) cache.orders.set(k, (r = reaches(q, order, input, memo)));
      return r;
    });
    cache.sets.set(sk, a);
    return a;
  };
}

/** 'thisRun' by the walk: from the approached ice at `from`, the Runner's credits and clicks as they are. */
function walkThisRun(state: GameState, server: string, opts: HoldOptions): Hold {
  const run = state.activeRun;
  const sv = state.corp.servers[server];
  const budget = state.runner.credits;
  const none: Hold = { holds: false, rez: null, rezCost: Infinity, need: 0, budget, margin: -budget, entries: 1 };
  const pos = opts.from ?? run?.icePosition ?? null;
  if (!run || !sv || pos === null) return none;
  const credits = opts.corpCredits ?? state.corp.credits;
  const must = sv.ice.filter(c => opts.mustRez?.includes(c.instanceId));
  const base = must.reduce((n, c) => n + rezCost(state, c), 0);
  // As before (Stage B2): the approached ice may be rezzable for less than its printed cost (Biawak's forfeit)
  const paidAnotherWay = base > credits && must.length > 0 && must.every(c => c.instanceId === sv.ice[run.icePosition ?? -1]?.instanceId && isLegalAction(state, { type: 'REZ_CARD', player: 'corp', cardInstanceId: c.instanceId }));
  if (base > credits && !paidAnotherWay) return none;
  const spare = paidAnotherWay ? 0 : credits - base;
  const open = (opts.further ?? true) ? sv.ice.slice(0, pos).filter(c => !c.isRezzed).slice(0, 10) : [];
  const start = walkStart(state, false);
  const ice0 = walkIce(state, start, sv.ice);
  const board = walkBoard(state, start, [{ server, ice: ice0 }]);
  let best = Infinity;
  let bestSet: string[] | null = null;
  let bestNeed = 0;
  let mostNeed = -Infinity;
  for (let mask = 0; mask < 1 << open.length; mask++) {
    const extra = open.filter((_, i) => mask & (1 << i));
    const cost = base + extra.reduce((n, c) => n + rezCost(state, c), 0);
    if (cost - base > spare || cost >= best) continue;
    const up = new Set([...must.map(c => c.instanceId), ...extra.map(c => c.instanceId)]);
    const view = withServerIce(state, sv.id, sv.ice.map(c => (up.has(c.instanceId) ? { ...c, isRezzed: true } : c)));
    const skipped = bypassesAhead(view, view.corp.servers[sv.id].ice.slice(0, pos + 1), true);
    const ice = ice0.map(c => ({ ...searchIce(c), inS: up.has(c.id), bypassed: skipped.has(c.id) }));
    // The Corp pays each rez as its ice is approached (6.4.3): it starts with the approached ice's cost still in hand
    const corp = spare + base;
    // The run's own credits: the fund and Overclock's; the cards that pay during it are the first state's (runCredits)
    const fund = run.bonusCredits + (run.badPublicityCredits ?? 0);
    const ws: WalkState = { ...firstState(state, start, state.runner.clicks, corp), fund };
    const need = new Walk(board, [{ server, ice }], undefined, false).fromIce(ws, pos);
    if (need > mostNeed) mostNeed = need;
    if (need > budget) {
      best = cost;
      bestSet = [...up];
      bestNeed = need;
    }
  }
  if (bestSet) return { holds: true, rez: bestSet, rezCost: best, need: bestNeed, budget, margin: bestNeed - budget, entries: 0 };
  const need = mostNeed === -Infinity ? 0 : mostNeed;
  return { ...none, need, margin: need - budget };
}
ai/cards/types.ts
import type { CardInstance, GameState, SideCode } from '../../core';
import type { Subroutine } from '../../core/scripts/types';
import type { CardProfile } from '../cardProfiles';
import type { CardValue } from '../cardValues';
import type { CorpEffect } from '../effectValues';
import type { CardSynergy } from '../synergyTags';
import type { RunOptions } from '../runs';

export type CounterType = 'credit' | 'virus' | 'power' | 'agenda';
export type CounterWorth = (state: GameState, card: CardInstance) => number;

/** What corpEffect works out once for every Corp card, before its own formula. */
export interface CorpEffectContext {
  /** Its rez cost, or 0 once rezzed (plan.rezPaid). */
  cost: number;
  /** Worth to the Corp of scoring a typical agenda from its deck. */
  agenda: number;
  /** Worth of a card in HQ. */
  card: number;
  /** Worth of a tag on the Runner. */
  tag: number;
  /** Risk a Runner turn of losing it, for perTurn: an asset's measured (assetRisk, bare), else 0.06 until V-C (V-B B3). */
  risk: number;
}

/**
 * What a card does at the points of a Runner's turn the hold count walks (Stage D item 1, brief 4.4), as its text says:
 * facts the walk applies to the state it carries (counters, rez flags, tags, credits), never a worth. Read only by the
 * hold count (corp/hold.ts): the Runner's run prices (gainsOnEncounter, runs.ts plannedSubroutines) do not read them.
 */
export interface HoldFacts {
  /** When the Runner's turn begins (rule 5.7.1): counters it places on itself, then a derez of its host ice once it holds this many (Tranquilizer). */
  runnerTurnStart?: { counters: { kind: CounterType; n: number }; derezHostAt?: number };
  /** When a turn ends: this ice derezzes itself (Lycian Multi-Munition). */
  turnEndDerezSelf?: true;
  /**
   * When the Corp rezzes this ice it chooses the subtypes the ice gains while it stays rezzed, one of these sets
   * (Lycian Multi-Munition: "choose 1 or more subtypes among barrier, code gate, and sentry"). The walk takes the
   * choice that keeps the Runner out (ruling 6).
   */
  rezChoosesSubtypes?: string[][];
  /**
   * An additional cost to rez this ice: the Corp takes 1 bad publicity or removes 1 tag, its choice (Valentão, Piranhas;
   * 1.14.3a). The walk takes the choice worse for the Runner (ruling 6); bad publicity taken during a run fills the fund
   * from the next run on (6.9.1b, 10.6.3a, 10.6.3c).
   */
  rezBadPublicityOrTag?: true;
  /**
   * When the Corp rezzes this ice during a run against its server (Flyswatter, Ping, Bumi 1.0), or, on an identity, any
   * ice of these subtypes during a run (Thunderbolt Armaments): what follows. A choice the Corp makes ("you may trash 1
   * installed trojan") is the Corp's: the walk takes the answer that keeps the Runner out (ruling 6).
   */
  rezDuringRun?: {
    purgeVirus?: true;
    tags?: number;
    corpMayTrashInstalled?: 'trojan';
    /** Identity: the rezzed ice of these printed subtypes gains this subroutine after its others, for the run (9.8.3e; its +1 strength is not modelled). */
    anyIce?: { subtypes: string[]; gains: string };
  };
  /**
   * When the Runner encounters this ice (6.9.3a). `loses`: credits it loses. `toll`: what happens unless the Runner
   * pays any ONE of `unless`, its choice (Funhouse: the run ends unless it takes 1 tag; Seraph: it loses 3 unless it
   * suffers 2 net damage or takes 1 tag; Jaguarundi: a tag unless it spends a click), active from `threatAtLeast`.
   */
  encounter?: {
    loses?: number;
    toll?: { endRun?: true; loses?: number; tags?: number };
    unless?: { tags?: number; netDamage?: number; clicks?: number };
    threatAtLeast?: number;
  };
  /**
   * A Runner card hosted on ice: whenever its host is encountered, if the host is not of `unlessSubtype`, the Runner may
   * pay `creditsPerSubroutine` for each subroutine the host has to bypass it (Physarum Entangler; 6.5.8a).
   */
  hostBypass?: { creditsPerSubroutine: number; unlessSubtype: 'barrier' | 'code gate' | 'sentry' };
  /** Trashed when the Corp purges virus counters (Physarum Entangler). */
  trashedOnPurge?: true;
  /** A program hosted on ice: a hosted counter of this kind breaks 1 subroutine on its host (Botulus). */
  breaksHostSubroutine?: { counter: 'virus' };
  /**
   * An agenda in the Corp's score area: "When this turn ends, derez `count` pieces of ice protecting that server", the
   * server it was used on this turn kept by the engine in the turn flag `${flag}:${instance id}` (its position in the
   * server list, plus 1) (Lightning Laboratory). With `count` or fewer rezzed there, all of them are derezzed; with
   * more, the Corp picks `count`, and the walk asks each pick (follow-up 4, ruling 8 (a)).
   */
  turnEndDerez?: { count: number; flag: string };
  /** A Runner card: each hosted counter of this kind pays `credits`, no click, during the Runner's turn (Coalescence; 9.5.1). */
  counterCredits?: { counter: 'power'; credits: number };
  /**
   * A Runner card: whenever a run begins (6.9.1c) it places `place` credits on itself; when it holds `takeAllAt` or more,
   * the Runner takes all of them (1.10.4a), trashes it and draws `draw` (Side Hustle).
   */
  runBeginCredits?: { place: number; takeAllAt: number; draw: number };
  /**
   * A Runner card: the first time each turn a run begins (6.9.1c), the Runner may trash 1 of its other installed cards
   * to gain credits equal to that card's printed install cost and draw `draw` ("Knickknack" O'Brian). The walk counts it
   * as a bound (follow-up 4, design answer): the largest printed install cost among the other installed cards, gained
   * with the card kept.
   */
  firstRunTrashForCost?: { draw: number };
}

/**
 * Everything the AI knows about one card's worth, in one place (2026-11-03,
 * from Gemini's CardFacts review). What a card does stays in its engine
 * script; this is only how the AI prices it. Every part is optional.
 */
export interface CardAI {
  /** Deck-aware synergy tags: what it gives and wants, and when its effect applies (synergyTags.ts). Every card has one. */
  synergy?: CardSynergy;
  /** Hand-set numbers: the fallback when effect values are off or a value loop is cut short (cardValues.ts). */
  value?: CardValue;
  /** Money cards: what they pay out and when (cardProfiles.ts). */
  profile?: CardProfile;
  /** Corp asset or upgrade: its worth from what it does, in credits (effectValues.ts corpEffect). */
  corp?: (state: GameState, code: string, ctx: CorpEffectContext) => CorpEffect;
  /** Runner rig card that isn't an icebreaker: its worth installed, in credits (effectValues.ts runnerEffect). */
  runner?: (state: GameState, code: string, card?: CardInstance) => number;
  /** Corp root card: its worth once rezzed, less the rez cost, where corp() doesn't say (effectValues.ts rezzedWorth). */
  rezzed?: (state: GameState, card: CardInstance, rezCost: number) => number;
  /** A run it starts (run event, run ability): what the card adds to that run (prompts.ts runEventOptions; runs.ts RunOptions). */
  run?: (state?: GameState) => RunOptions;
  /** One counter on it, by type (counterValues.ts COUNTER_WORTH). */
  counters?: Partial<Record<CounterType, CounterWorth>>;
  /** One counter on it worked out from what it turns into, while plan.counterFormulas is on. */
  counterFormulas?: Partial<Record<CounterType, CounterWorth>>;
  /** Corp card faceup in Archives that plays again from there: its worth waiting there (read by archivedWorth; its evaluate reader went with plan.oneCurrency in audit Step 3). */
  archived?: (state: GameState) => number;
  /** Corp operation that buys clicks or advancements to finish an agenda this turn: plan.finishSetup ranks it, and corpAI
   * operationBonus adds no bonus of its own (tuning pass 1, the old plan.oneSetupRule). */
  setup?: true;
  /** Rezzed ice that gains subroutines when the Runner encounters it, by the state now (Starlit Knight): the ones it
   * would gain on the next encounter this run, after its other subroutines, or none if it already has them. Run
   * planning reads them through runs.ts plannedSubroutines, so a run is priced against the ice as it will be met. */
  gainsOnEncounter?: (state: GameState, ice: CardInstance) => Subroutine[];
  /** Corp card whose damage can't all land on the Corp's own turn (plan.corpTurnDamageOwn, effectValues.ts damageThreat):
   * the most it can deal there, by the state now. Unset: what its text says (on access, during a run, if tagged: 0). */
  corpTurnDamage?: number | ((state: GameState) => number);
  /** Runner rig card that may spend one of its counters, when the Runner breaches `server`, to access 1 more card
   * (Devadatta Drone on R&D): runs.ts runScore counts the access on a run there while a counter is left, and charges the
   * counter at its worth (counterValues.ts counterWorth). */
  breachAccess?: { server: string; counter: CounterType };
  /** Agenda with Dividends N: agenda counters placed for each excess advancement counter when it is scored (the Corp
   * over-advances it: corpAI overAdvance; counted scoring leaves it to the Corp at its requirement: winNow.ts,
   * countedScore.ts). */
  dividends?: number;
  /** Card that pays its owner credits when its turn begins (a rezzed Corp card, an installed Runner card): the credits,
   * and whether they are taken from the credits hosted on it (a campaign, Smartware Distributor: no more than it holds).
   * Counted scoring reads it as the Corp's next-turn income (countedScore.ts knownIncome) and as the Runner's turn-start
   * money (runnerBudget). */
  turnIncome?: { credits: number; hosted?: true };
  /** What it does at the points of the Runner's turn the hold count walks (HoldFacts; Stage D item 1). */
  holdFacts?: HoldFacts;
  /** Runner card that pays off an Archives run, or turns one into a run on something else (Maintenance Access, Baker):
   * the Corp ices and rezzes Archives only against these, or with an agenda there (rezModel.ts archivesWantsIce). */
  archivesPayoff?: true;
  /** Agenda that gains the Corp credits when it is scored (Offworld Office 7): counted scoring's money left after a
   * two-turn line (countedScore.ts afterLineFloor). */
  scoreCredits?: number;
  /** Installed Runner card with a click ability that pays credits, one use on the Runner's next turn (countedScore.ts
